# PROVENANCE: test fixture for reasoning-depth-spec.md §8 T1 (Steelers @ Browns, Week 4 2026).
# All values are taken from the spec's own worked example (§3, §6.1) and
# tnf-intelligence-program-2026-10-01.md (Monken case study, #5 pass rush):
# - CLE missing 2 interior OL starters (spec §6.1 example trace, CORPUS)
# - Monken 2026 quick-game 0.639 vs league avg 0.508; air yards 8.33 -> 6.12 (Track 2, COMPUTED)
# - PIT pass rush rank 5 (program doc §4: "vs the #5 pass rush")
# - Watson INT splits: 3-5% under hit vs 0.8-3.2% clean (spec §6.1 L4 counter-argument, Track 1)
# - Trust signals: Rodgers-Metcalf video (frustration), Wilson rising role (program doc §1)
# FIXTURE NOTE: ttt_seconds=2.18 is stipulated to satisfy the spec's stated pre-kickoff
# condition (TTT < 2.3s, "both thresholds were satisfied in Weeks 1-3 data", §8 T1).
# Production providers MUST supply measured TTT; the stub exists only so T1 is deterministic.
"""In-memory stub providers seeded with the PIT@CLE Week 4 2026 fixture."""
from __future__ import annotations

from .providers import (
    CoachProfile,
    CoachingProvider,
    DataGapError,
    OLProvider,
    OLState,
    PressureSplits,
    ProviderRegistry,
    QBBehaviorProfile,
    QBBehaviorProvider,
    SchemeFingerprint,
    TrustSignal,
    TrustSignalProvider,
)
from .types import Verification

WEEK, SEASON = 4, 2026


class StubQBBehaviorProvider(QBBehaviorProvider):
    def get_qb_profile(self, qb_id: str, week: int, season: int) -> QBBehaviorProfile:
        if qb_id == "deshaun-watson":
            return QBBehaviorProfile(
                qb_id=qb_id, name="Deshaun Watson", team="CLE", week=week, season=season,
                epa_per_dropback=0.02, pressure_to_sack_rate=0.18,
                aggressiveness=0.12, adot=6.9, target_hhi=0.14,
                verification=Verification.CORPUS)
        if qb_id == "aaron-rodgers":
            return QBBehaviorProfile(
                qb_id=qb_id, name="Aaron Rodgers", team="PIT", week=week, season=season,
                target_hhi=0.21, trust_target_share_3rd=0.34,
                verification=Verification.CORPUS)
        raise DataGapError("qb_behavior", f"no fixture profile for {qb_id}")

    def get_pressure_splits(self, qb_id: str, week: int, season: int) -> PressureSplits:
        if qb_id == "deshaun-watson":
            return PressureSplits(
                qb_id=qb_id, int_rate_clean=0.020, int_rate_pressure=0.040,
                epa_per_dropback_clean=0.08, epa_per_dropback_pressure=-0.31,
                verification=Verification.CORPUS)  # spec §6.1: 3-5% under hit vs 0.8-3.2% clean
        raise DataGapError("qb_behavior", f"no fixture pressure splits for {qb_id}")


class StubCoachingProvider(CoachingProvider):
    def get_coach_profile(self, coach_id: str, season: int) -> CoachProfile:
        if coach_id == "todd-monken":
            return CoachProfile(
                coach_id=coach_id, name="Todd Monken", role="HC", team="CLE", season=season,
                early_down_pass_rate=0.562,
                yoy_delta_note="quick-game proxy 0.476 (2023 BAL) -> 0.518 (2025 BAL) -> 0.639 (2026 CLE)",
                verification=Verification.COMPUTED)
        raise DataGapError("coaching_scheme", f"no fixture profile for {coach_id}")

    def get_scheme_fingerprint(self, team: str, week: int, season: int) -> SchemeFingerprint:
        if team == "CLE":
            return SchemeFingerprint(
                team=team, week=week, season=season,
                quickgame_rate=0.639, avg_air_yards=6.12, ttt_seconds=2.18,
                early_down_pass_rate=0.562, motion_rate=0.41,
                verification=Verification.COMPUTED)
        if team == "PIT":
            return SchemeFingerprint(
                team=team, week=week, season=season,
                quickgame_rate=0.44, avg_air_yards=7.8, motion_rate=0.52,
                verification=Verification.COMPUTED)
        raise DataGapError("coaching_scheme", f"no fixture fingerprint for {team}")


class StubTrustSignalProvider(TrustSignalProvider):
    def get_trust_signals(self, team: str, week: int, season: int) -> tuple[TrustSignal, ...]:
        if team == "PIT":
            return (
                TrustSignal(player_id="aaron-rodgers", signal_type="frustration",
                            text="viral video: Rodgers burying Metcalf ('this mfer sucks ass')",
                            source_url="x-intake-registry/trust-signal-intake",
                            observed_at="2026-09-30", verification=Verification.SINGLE_SOURCE),
                TrustSignal(player_id="roman-wilson", signal_type="role_change",
                            text="usage trending up (3-5-7 receptions); last man in the trust circle",
                            source_url="x-intake-registry/trust-signal-intake",
                            observed_at="2026-10-01", verification=Verification.SINGLE_SOURCE),
            )
        return ()


class StubOLProvider(OLProvider):
    def get_ol_state(self, team: str, week: int, season: int) -> OLState:
        if team == "CLE":
            return OLState(
                team=team, week=week, season=season,
                starters_out=("CLE-C (out)", "CLE-LG (out)"),
                practice_status=(("CLE-C (out)", "DNP"), ("CLE-LG (out)", "DNP")),
                continuity_index=0.62, pressure_rate_allowed=0.31,
                verification=Verification.CORPUS)
        if team == "PIT":
            return OLState(team=team, week=week, season=season,
                           starters_out=(), continuity_index=0.88,
                           pressure_rate_allowed=0.24, verification=Verification.CORPUS)
        raise DataGapError("offensive_line", f"no fixture OL state for {team}")


def fixture_registry() -> ProviderRegistry:
    """All four providers wired (no UNCHECKED tracks for the T1 fixture)."""
    return ProviderRegistry(
        qb=StubQBBehaviorProvider(),
        coaching=StubCoachingProvider(),
        trust=StubTrustSignalProvider(),
        ol=StubOLProvider(),
    )


def fixture_game() -> dict:
    return {
        "away": "PIT", "home": "CLE", "week": WEEK, "season": SEASON,
        "qbs": {"CLE": "deshaun-watson", "PIT": "aaron-rodgers"},
        "playcallers": {"CLE": "Todd Monken"},
        "defense": {"PIT": {"pass_rush_rank": 5}},
    }


def fixture_league_avgs() -> dict:
    return {"quickgame_rate": 0.508}

# PROVENANCE: implements reasoning-depth-spec.md §2.6 (persisted, content-addressed,
# resumable traces), §6.1 (trace schema), §8 T7 (resume, don't restart).
# Converged 2026-10-02: the store persists reasoning's CANONICAL ReasoningTrace
# (via reasoning.trace serialization). Legacy façade-DTO payloads still load
# (converted to canonical on read) so existing saved traces remain readable.
"""Trace persistence: content-addressed, append-only, resumable (façade store)."""
from __future__ import annotations

import hashlib
import json
import os
from abc import ABC, abstractmethod
from datetime import datetime, timezone
from typing import Any, Optional

from reasoning import ReasoningTrace as CanonicalTrace
from reasoning.enums import ChecklistVerdict, ReasoningDepth
from reasoning.trace import trace_from_dict as _canonical_from_dict
from reasoning.trace import trace_to_dict as _canonical_to_dict

from .types import ReasoningTrace as DtoTrace


def utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def make_trace_id(game: dict[str, Any], depth: ReasoningDepth,
                  levels: dict[str, Any]) -> str:
    """Content-addressed id: sha1 of the canonical (game, depth, levels) payload."""
    canonical = json.dumps({"game": game, "depth": depth.value, "levels": levels},
                           sort_keys=True, default=str)
    return "trace_" + hashlib.sha1(canonical.encode()).hexdigest()[:16]


def _dto_to_canonical(rec: dict[str, Any]) -> CanonicalTrace:
    """Convert a legacy façade-DTO payload to the canonical trace."""
    from reasoning import EscalationEntry
    trace = CanonicalTrace(
        trace_id=rec["trace_id"],
        depth=ReasoningDepth(rec["depth"]),
        game=rec.get("game", {}),
        label=rec.get("label", "DRAFT"),
    )
    for e in rec.get("escalation_log", []):
        trace.escalation_log.append(EscalationEntry(
            from_depth=ReasoningDepth(e["from"]),
            to_depth=ReasoningDepth(e["to"]),
            trigger=e["trigger"], at=e.get("at", "")))
    trace.levels = rec.get("levels", {})
    trace.checklist = {k: ChecklistVerdict(v) for k, v in rec.get("checklist", {}).items()}
    trace.tool_calls = rec.get("tool_calls", [])
    return trace


class TraceStore(ABC):
    @abstractmethod
    def save(self, trace: Any) -> str: ...
    @abstractmethod
    def load(self, trace_id: str) -> Optional[CanonicalTrace]: ...


class FileTraceStore(TraceStore):
    """JSONL file store. One line per save; resume appends a new level, never rewrites."""

    def __init__(self, path: str):
        self.path = path
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)

    def save(self, trace: Any) -> str:
        if isinstance(trace, CanonicalTrace):
            body = {"kind": "canonical", "record": _canonical_to_dict(trace)}
        else:  # legacy DTO
            body = {"kind": "dto", "record": trace.to_dict()}
        body["saved_at"] = utcnow_iso()
        with open(self.path, "a", encoding="utf-8") as f:
            f.write(json.dumps(body, default=str) + "\n")
        return trace.trace_id

    def load(self, trace_id: str) -> Optional[CanonicalTrace]:
        if not os.path.exists(self.path):
            return None
        latest: Optional[dict] = None
        with open(self.path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                rec = json.loads(line)
                if _record_trace_id(rec) == trace_id:
                    latest = rec
        if latest is None:
            return None
        kind = latest.get("kind")
        inner = latest.get("record", latest)
        if kind == "canonical":
            return _canonical_from_dict(inner)
        if kind == "dto":
            return _dto_to_canonical(inner)
        # Legacy flat payloads (pre-envelope): try canonical, fall back to DTO.
        try:
            return _canonical_from_dict(latest)
        except (ValueError, KeyError, TypeError):
            return _dto_to_canonical(latest)


def _record_trace_id(rec: dict[str, Any]) -> Optional[str]:
    """Extract the trace id from any known payload shape."""
    inner = rec.get("record")
    if isinstance(inner, dict):
        fields = inner.get("fields")
        if isinstance(fields, dict) and fields.get("trace_id"):
            return fields["trace_id"]
        if inner.get("trace_id"):
            return inner["trace_id"]
    if rec.get("trace_id"):
        return rec["trace_id"]
    fields = rec.get("fields")
    if isinstance(fields, dict):
        return fields.get("trace_id")
    return None


def resume_trace(store: TraceStore, trace_id: str, new_level_name: str,
                 new_level: dict[str, Any], trigger: str) -> CanonicalTrace:
    """Merge new signals as a NEW level entry; original levels are never rewritten (T7)."""
    from reasoning import EscalationEntry
    old = store.load(trace_id)
    if old is None:
        raise KeyError(f"no such trace: {trace_id}")
    merged_levels = dict(old.levels)
    if new_level_name in merged_levels:
        raise ValueError(f"level {new_level_name!r} already exists — refusing to overwrite")
    merged_levels[new_level_name] = new_level
    new_trace = CanonicalTrace(
        trace_id=make_trace_id(old.game, old.depth, merged_levels),
        game=dict(old.game),
        depth=old.depth,
        escalation_log=list(old.escalation_log),
        levels=merged_levels,
        checklist=dict(old.checklist),
        tool_calls=list(old.tool_calls) + [
            {"tool": "trace/resume", "args": {"from": trace_id, "level": new_level_name},
             "returned": trigger}],
        label=old.label,
    )
    new_trace.escalation_log.append(
        EscalationEntry(from_depth=old.depth, to_depth=old.depth,
                        trigger=f"resume_merge:{trigger}", at=utcnow_iso()))
    return new_trace

# Provenance: stability/governance gate for every behavioral rate.
# Implements: partition-01-qb.md #12 (D/S/I audit per 1184 — flag D<0.5 or
# I<0.2 for shrinkage; Minerva Seal >=80 per 2048; n<30 flag per Challenge M;
# 100-dropback pipeline minimum); the answer to Garrett's 17:34 audit
# challenge for this lane: every profile number ships with n, stability
# grade, and recency model.
"""Audit gates: decide whether a computed metric may enter a profile."""
from __future__ import annotations

from dataclasses import dataclass

from . import metrics as M
from .profile import MetricValue, SeasonProfile, Verification

# Governance thresholds (from research, not invented)
D_SHRINK_THRESHOLD = 0.5   # 1184: flag D<0.5 metrics for shrinkage/removal
N_PROFILE_MIN = 100         # pipeline hard minimum (dropbacks/season)
N_SMALL_SAMPLE = 30        # Challenge M: below this is a slate read, not a profile input
N_TINY_SAMPLE = 12         # partition-04: n=12 graduation gate lets noise through — floor, not a pass


@dataclass
class GateResult:
    metric: str
    passed: bool
    reason: str


def sample_gate(key: str, m: MetricValue) -> GateResult:
    """n-based admission: below the tiny-sample floor it is not publishable;
    below 30 it is a slate read, not a profile input."""
    n = m.n or 0
    if n < N_TINY_SAMPLE:
        return GateResult(key, False, f"n={n} below tiny-sample floor {N_TINY_SAMPLE}: do not publish")
    if n < N_SMALL_SAMPLE:
        return GateResult(key, False, f"n={n} < {N_SMALL_SAMPLE}: slate read only, not a profile input")
    return GateResult(key, True, f"n={n} adequate")


def discrimination_gate(key: str, group_means: list[float]) -> GateResult:
    """D/S/I audit: D<0.5 -> shrink, don't drop (1184: relevance overrides)."""
    d = M.discrimination(group_means)
    if d < D_SHRINK_THRESHOLD:
        return GateResult(key, False,
                          f"D={d:.3f} < {D_SHRINK_THRESHOLD}: shrink toward prior, do not publish raw")
    return GateResult(key, True, f"D={d:.3f} adequate")


def audit_season_profile(sp: SeasonProfile) -> list[GateResult]:
    """Run admission gates over every metric in a season profile."""
    results = []
    for key, m in sp.metrics.items():
        results.append(sample_gate(key, m))
    return results


def failing_gates(results: list[GateResult]) -> list[GateResult]:
    return [r for r in results if not r.passed]


def mark_weak_links(sp: SeasonProfile, results: list[GateResult]) -> SeasonProfile:
    """Demote failing metrics to SINGLE_SOURCE with the gate reason.

    They stay in the profile (honest display) but can never be load-bearing
    at L4+ without an explicit flag (reasoning-depth-spec T5).
    """
    failed = {r.metric for r in failing_gates(results)}
    for key in failed:
        m = sp.metrics.get(key)
        if m is not None and m.verification == Verification.COMPUTED:
            m.verification = Verification.SINGLE_SOURCE
            m.note = (m.note + " | AUDIT: " if m.note else "AUDIT: ") + \
                     next(r.reason for r in results if r.metric == key)
    return sp

# Provenance: QB identity resolution.
# Extends: ~/workspace/qb-behavioral-profiles/code/compute_metrics.py
# (GSIS passer_player_id as the stable key across the 2019 name-format
# change; scramble backfill from rusher_player_id).
"""QB identity: the stable key is the GSIS id, never the name string."""
from __future__ import annotations


def backfill_scramble_passer(passer_id: str | None, rusher_id: str | None,
                             is_scramble: bool) -> str | None:
    """nflfastR leaves passer_player_id null on scrambles; the rusher is the QB.

    Pure function of one play's fields so it is unit-testable.
    """
    if passer_id:
        return passer_id
    if is_scramble and rusher_id:
        return rusher_id
    return None


def build_name_map(rosters: list[dict]) -> dict[str, str]:
    """gsis_id -> canonical full_name from nflverse rosters.

    Later rows win (handles mid-career name corrections); null ids skipped.
    """
    m: dict[str, str] = {}
    for r in rosters:
        gid = r.get("gsis_id")
        name = r.get("full_name")
        if gid and name:
            m[gid] = name
    return m


def canonical_name(passer_id: str | None, name_map: dict[str, str]) -> str:
    """Canonical display name; falls back to the raw id, never empty."""
    if not passer_id:
        return "unknown"
    return name_map.get(passer_id, passer_id)


def build_name_map_from_pbp(pbp_id_name_pairs: list[tuple[str | None, str | None]]) -> dict[str, str]:
    """Build a gsis_id -> name map from (passer_player_id, passer_player_name)
    pairs in local pbp data. No network needed.

    Most common name wins per id (handles the 2019 nflverse name-format
    change: one id can carry two name strings across eras). Names sourced
    this way are nflverse display names, not roster canonical names —
    callers that need roster-canonical names should pass an explicit map.
    """
    from collections import Counter
    votes: dict[str, Counter] = {}
    for pid, pname in pbp_id_name_pairs:
        if pid and pname:
            votes.setdefault(pid, Counter())[pname] += 1
    return {pid: c.most_common(1)[0][0] for pid, c in votes.items()}


def sanitize_filename(name: str) -> str:
    """Filesystem-safe stem for per-QB artifacts."""
    return "".join(c if c.isalnum() else "_" for c in name)

# PROVENANCE — qb-behavior / situational / serve.py
# Runtime server for c02 situational tables (stdlib + csv ONLY — no polars,
# per tests/README.md rule 5; the build job did the heavy lifting).
# Implements: corpus-intelligence/deep/c02/buildable-systems.md (Systems 1–2);
# verified-claims.md SIT-5 (EB ladder M=25), SIT-6 (cells), PRESS-1/2 (guards).
# Cell definitions: situational/cells.py (single source of truth).
"""Serve precomputed situational tables.

INT-by-situation uses the EB shrinkage ladder (verified-claims.md SIT-5):
  cell = (w + M * p_parent) / (n + M), M = 25, league -> team -> QB.
Null floors: no leaf at n < 30 (auto back-off); no QB pressure (p=1) cell
below 100 pooled pressured dropbacks (proposal :23, via a06).
"""
from __future__ import annotations

import csv
import os
from typing import Any

M_EB = 25                      # SIT-5: denoised-rate auditor precedent
INT_BASELINE = 0.01867         # c01 metrics.py INT_BASELINE_PER_DROPBACK
LEAF_MIN_N = 30                # SIT-5 null floor
MIN_PRESSURED_DROPBACKS = 100  # proposal :23


def _eb(n: int, w: int, parent: float) -> float:
    return (w + M_EB * parent) / (n + M_EB)


class SituationalStore:
    """Loads data/*.csv once; serves weekly/season rows and INT cells."""

    def __init__(self, data_dir: str):
        self.data_dir = data_dir
        self.weekly: dict[tuple, dict] = {}   # (qb_id, season, week) -> row
        self.season: dict[tuple, dict] = {}   # (qb_id, season) -> row
        self.cells: dict[tuple, tuple[int, int]] = {}  # (scope, id, season_key, cell) -> (n, w)
        self.meta: dict[str, str] = {}
        self._load()

    # -- loading ---------------------------------------------------------
    def _load(self) -> None:
        p = os.path.join(self.data_dir, "qb_weekly.csv")
        if os.path.exists(p):
            with open(p, newline="") as f:
                for r in csv.DictReader(f):
                    self.weekly[(r["qb_id"], int(r["season"]), int(r["week"]))] = r
        p = os.path.join(self.data_dir, "qb_season.csv")
        if os.path.exists(p):
            with open(p, newline="") as f:
                for r in csv.DictReader(f):
                    self.season[(r["qb_id"], int(r["season"]))] = r
        p = os.path.join(self.data_dir, "int_cells.csv")
        if os.path.exists(p):
            with open(p, newline="") as f:
                for r in csv.DictReader(f):
                    self.cells[(r["scope"], r["id"], r["season_key"], r["cell"])] = (
                        int(r["n"]), int(r["w"]))
        p = os.path.join(self.data_dir, "meta.csv")
        if os.path.exists(p):
            with open(p, newline="") as f:
                for r in csv.DictReader(f):
                    self.meta[r["key"]] = r["value"]

    # -- weekly / season rows --------------------------------------------
    def weekly_row(self, qb_id: str, season: int, week: int) -> tuple[dict | None, int | None]:
        """Latest row with week <= requested (point-in-time). Returns (row, week_used)."""
        cands = [(w, r) for (q, s, w), r in self.weekly.items()
                 if q == qb_id and s == season and w <= week]
        if not cands:
            return None, None
        w, r = max(cands, key=lambda t: t[0])
        return r, w

    def season_row(self, qb_id: str, season: int) -> dict | None:
        return self.season.get((qb_id, season))

    def max_week(self, season: int) -> int | None:
        ws = [w for (q, s, w) in self.weekly if s == season]
        return max(ws) if ws else None

    def seasons(self) -> list[int]:
        return sorted({s for (q, s) in self.season})

    # -- INT cells ---------------------------------------------------------
    @staticmethod
    def season_key_for(season: int, week: int | None, max_week_2026: int | None = None) -> str:
        if season == 2026:
            # cap at the latest charted week (point-in-time: never reach past data)
            w = week if week is not None else max_week_2026
            if max_week_2026 is not None and w is not None:
                w = min(w, max_week_2026)
            return f"2026_w{w}"
        return str(season)

    def _pool_seasons(self, season_key: str) -> list[int]:
        if season_key.startswith("2026_w"):
            return [2024, 2025, 2026]
        s = int(season_key)
        return [x for x in (s - 2, s - 1, s)]

    def _cell(self, scope: str, id_: str, season_key: str, cell: str) -> tuple[int, int]:
        return self.cells.get((scope, id_, season_key, cell), (0, 0))

    def pool_pressured_dropbacks(self, qb_id: str, season_key: str) -> int:
        """Pooled pressured (floor) dropbacks for the :23 guard."""
        total = 0
        for s in self._pool_seasons(season_key):
            r = self.season.get((qb_id, s))
            if r and r.get("n_press"):
                total += int(float(r["n_press"]))
        return total

    def int_rate(self, qb_id: str, team: str | None, season_key: str,
                 cell: str) -> dict[str, Any]:
        """EB-shrunk INT rate for one cell. Returns rate (0-1), n, level,
        and the ladder components. Never raises on missing data (backs off)."""
        nL, wL = self._cell("L", "NFL", season_key, cell)
        nT, wT = self._cell("T", team or "", season_key, cell)
        nQ, wQ = self._cell("Q", qb_id, season_key, cell)
        rate_L = _eb(nL, wL, INT_BASELINE)
        rate_T = _eb(nT, wT, rate_L)
        rate_Q = _eb(nQ, wQ, rate_T)
        p = int(cell.split("_")[0][1:])
        if nQ >= LEAF_MIN_N and (p == 0 or
                                 self.pool_pressured_dropbacks(qb_id, season_key) >= MIN_PRESSURED_DROPBACKS):
            level, rate, n = "qb", rate_Q, nQ
        elif nT >= LEAF_MIN_N:
            level, rate, n = "team", rate_T, nT
        else:
            level, rate, n = "league", rate_L, nL
        return {"rate": rate, "n": n, "level": level,
                "rate_qb": rate_Q, "rate_team": rate_T, "rate_league": rate_L,
                "n_qb": nQ, "n_team": nT, "n_league": nL}

    def int_rate_marginal(self, qb_id: str, team: str | None, season_key: str,
                          pressured: int) -> dict[str, Any]:
        """EB-shrunk INT rate marginal over all cells with p=pressured."""
        agg: dict[tuple[str, str, str], list[int]] = {}
        for (scope, id_, sk, cell), (n, w) in self.cells.items():
            if sk != season_key or not cell.startswith(f"p{pressured}_"):
                continue
            k = (scope, id_)
            a = agg.setdefault(k, [0, 0])
            a[0] += n
            a[1] += w
        nL, wL = agg.get(("L", "NFL"), [0, 0])
        nT, wT = agg.get(("T", team or ""), [0, 0])
        nQ, wQ = agg.get(("Q", qb_id), [0, 0])
        rate_L = _eb(nL, wL, INT_BASELINE)
        rate_T = _eb(nT, wT, rate_L)
        rate_Q = _eb(nQ, wQ, rate_T)
        if nQ >= LEAF_MIN_N and (pressured == 0 or
                                 self.pool_pressured_dropbacks(qb_id, season_key) >= MIN_PRESSURED_DROPBACKS):
            level, rate, n = "qb", rate_Q, nQ
        elif nT >= LEAF_MIN_N:
            level, rate, n = "team", rate_T, nT
        else:
            level, rate, n = "league", rate_L, nL
        return {"rate": rate, "n": n, "level": level,
                "rate_qb": rate_Q, "rate_team": rate_T, "rate_league": rate_L,
                "n_qb": nQ, "n_team": nT, "n_league": nL}

    def int_rate_for_situation(self, qb_id: str, team: str | None, season: int,
                               week: int | None, situation: dict,
                               max_week_2026: int | None = None) -> dict[str, Any]:
        """INT rate for a query situation dict {pressured (0/1), qtr,
        score_differential, yardline_100, down, ydstogo}. Encodes via
        cells.int_cell_from_play — the same function the build used."""
        from .cells import int_cell_from_play
        key = self.season_key_for(season, week, max_week_2026)
        play = {
            "qb_hit": 1 if situation.get("pressured") else 0,
            "sack": 0,
            "qtr": situation.get("qtr"),
            "score_differential": situation.get("score_differential"),
            "yardline_100": situation.get("yardline_100"),
            "down": situation.get("down"),
            "ydstogo": situation.get("ydstogo"),
        }
        cell = int_cell_from_play(play)
        out = self.int_rate(qb_id, team, key, cell)
        out["cell"] = cell
        out["season_key"] = key
        return out

# PROVENANCE — qb-behavior / situational / specs.py
# Implements c01's SplitSpec protocol (qb-behavior/src/qb_behavior/splits.py:
# name, dimensions, compute(frame: pl.DataFrame) -> {dimension_tuple: {metric: value}}).
# c02 OWNS these specs per qb-behavior/README.md ("Interface contract with c02"):
# situational split matrices + trust-target splits. The build job runs them via
# engine frames (never reloading pbp); the runtime server reads the precomputed
# CSVs the build job writes.
# Research: corpus-intelligence/deep/c02/buildable-systems.md (Systems 1–3);
# verified-claims.md PRESS-1..14, SIT-1..9, TRUST-1..10.
"""c02 SplitSpec implementations (c01 protocol).

Cell assignment funnels through situational/cells.py (single source of truth)
via one map_elements bucketize pass, so the build-time tables and any live
apply_split() call can never disagree on a cell definition.
"""
from __future__ import annotations

import polars as pl

from .cells import (
    TRUST_SITUATIONS,
    int_cell_from_play,
    pressure_floor,
    trust_situation,
)

BUCKET_COLS = ["qb_hit", "sack", "qtr", "score_differential", "yardline_100",
               "down", "ydstogo", "game_seconds_remaining"]


def _row_dict(row: dict) -> dict:
    return {k: row.get(k) for k in BUCKET_COLS}


def bucketize(frame: pl.DataFrame) -> pl.DataFrame:
    """Add `_cell` (INT grid key), `_p` (pressure floor 0/1), `_trust`
    (list of trust situations) from cells.py — the only cell-assignment path."""
    existing = [c for c in BUCKET_COLS if c in frame.columns]

    def _buckets(r: dict) -> dict:
        d = {k: r.get(k) for k in BUCKET_COLS}
        return {
            "p": pressure_floor(d["qb_hit"], d["sack"]),
            "cell": int_cell_from_play(d),
            "trust": [s for s in TRUST_SITUATIONS if trust_situation(s, d)],
        }

    return frame.with_columns(
        pl.struct(existing).map_elements(
            _buckets,
            return_dtype=pl.Struct({
                "p": pl.Int64,
                "cell": pl.String,
                "trust": pl.List(pl.String),
            }),
        ).alias("_b")
    )


def _int_rate(sub: pl.DataFrame) -> tuple[int, int, float | None]:
    """(n_att, n_int, int_rate_0_1) on a frame with pass_attempt/interception."""
    att = sub.filter(pl.col("pass_attempt") == 1) if "pass_attempt" in sub.columns else sub
    n = len(att)
    w = int(att["interception"].sum()) if n and "interception" in att.columns else 0
    return n, w, (w / n if n else None)


def _epa_mean(sub: pl.DataFrame) -> float | None:
    if len(sub) == 0 or "epa" not in sub.columns:
        return None
    v = sub["epa"].mean()
    return None if v is None else float(v)


class PressureFloorSplit:
    """Clean vs pressured on the FLOOR definition.

    c01 protocol: name / dimensions / compute(frame) -> {(p,): metrics}.
    Sensitivity = epa(clean) - epa(pressured) with the standard error of the
    difference (verified-claims.md PRESS-1, PRESS-14). Reported alongside the
    clean baseline (CH-PRESS-4: never rank QBs on the raw gap alone).
    """

    name = "pressure_floor"
    dimensions = ("pressured_floor",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        cells: dict[tuple, dict] = {}
        for p in (0, 1):
            sub = f.filter(pl.col("_b").struct.field("p") == p)
            n_att, n_int, ir = _int_rate(sub)
            epa = _epa_mean(sub)
            var = sub["epa"].var() if len(sub) > 1 and "epa" in sub.columns else None
            cells[(str(p),)] = {
                "n": len(sub), "n_att": n_att, "n_int": n_int,
                "int_rate": ir, "epa_mean": epa,
                "epa_var": None if var is None else float(var),
            }
        c0, c1 = cells[("0",)], cells[("1",)]
        sens = (c0["epa_mean"] - c1["epa_mean"]
                if c0["epa_mean"] is not None and c1["epa_mean"] is not None else None)
        se = None
        if c0["epa_var"] is not None and c1["epa_var"] is not None and c0["n"] and c1["n"]:
            import math
            se = math.sqrt(c0["epa_var"] / c0["n"] + c1["epa_var"] / c1["n"])
        cells[("sensitivity",)] = {
            "sens_epa_floor": sens,
            "sens_se": se,
            "clean_epa_baseline": c0["epa_mean"],
            "note": ("sensitivity_epa_floor attenuated toward zero: clean cell "
                     "contains unflagged hurries (no hurry data in nflverse)"),
        }
        return cells


class INTSituationalSplit:
    """Raw INT counts per 288-cell grid (verified-claims.md SIT-6).

    compute() returns RAW (n, w) per cell — EB shrinkage to the
    league->team->QB ladder (M=25) happens at serve time in serve.py, where
    the pooled league/team cells are available. Engine lane only: actual
    interception occurrence, never the worthy-rate formula (SIT-9).
    """

    name = "int_situational"
    dimensions = ("p", "q", "s", "z", "d")

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        cells: dict[tuple, dict] = {}
        if len(f) == 0:
            return cells
        grp = f.group_by(pl.col("_b").struct.field("cell").alias("cell")).agg(
            pl.len().alias("n_all"),
            pl.col("interception").sum().alias("w_all"),
        )
        for r in grp.iter_rows(named=True):
            n_att, n_int, _ = _int_rate(
                f.filter(pl.col("_b").struct.field("cell") == r["cell"])
            )
            # n = dropbacks in cell (denominator for the rate), w = INTs.
            # Use attempts for w/n consistency with the INT recipe.
            cells[(r["cell"],)] = {"n": n_att, "w": n_int}
        return cells


class TrustSituationSplit:
    """Target concentration per trust situation (verified-claims.md TRUST-7).

    Runs on the TARGET frame (pass attempts with a receiver). Returns per
    situation the receiver target counts — HHI/shares computed at serve time
    with the shared c01 metrics primitives (import, not reimplement).
    """

    name = "trust_situation"
    dimensions = ("situation",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        out: dict[tuple, dict] = {}
        for s in TRUST_SITUATIONS:
            sub = f.filter(pl.col("_b").struct.field("trust").list.contains(s))
            counts: dict[str, int] = {}
            ay: dict[str, float] = {}
            if len(sub) and "receiver_player_id" in sub.columns:
                g = sub.group_by("receiver_player_id").agg(
                    pl.len().alias("t"),
                    pl.col("air_yards").sum().alias("ay") if "air_yards" in sub.columns
                    else pl.len().alias("ay"),
                )
                for r in g.iter_rows(named=True):
                    rid = str(r["receiver_player_id"])
                    counts[rid] = r["t"]
                    ay[rid] = float(r["ay"] or 0.0)
            out[(s,)] = {"targets": counts, "air_yards": ay, "n": len(sub)}
        return out


class DownDistanceSplit:
    """Marginal down/distance cells (INT-grid component)."""

    name = "down_distance"
    dimensions = ("d",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        out: dict[tuple, dict] = {}
        for d in ("d0", "d1", "d2", "d3"):
            sub = f.filter(pl.col("_b").struct.field("cell").str.contains(f"_({d})$"))
            n_att, n_int, ir = _int_rate(sub)
            out[(d,)] = {"n": len(sub), "n_att": n_att, "n_int": n_int,
                         "int_rate": ir, "epa_mean": _epa_mean(sub)}
        return out


class FieldZoneSplit:
    """Marginal field-zone cells (INT-grid component)."""

    name = "field_zone"
    dimensions = ("z",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        out: dict[tuple, dict] = {}
        for z in ("z0", "z1", "z2"):
            sub = f.filter(pl.col("_b").struct.field("cell").str.contains(f"_(z{z[1]})_"))
            n_att, n_int, ir = _int_rate(sub)
            out[(z,)] = {"n": len(sub), "n_att": n_att, "n_int": n_int,
                         "int_rate": ir, "epa_mean": _epa_mean(sub)}
        return out


class ScriptSplit:
    """Marginal game-script cells (INT-grid component)."""

    name = "script"
    dimensions = ("s",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        out: dict[tuple, dict] = {}
        for s in ("s0", "s1", "s2"):
            sub = f.filter(pl.col("_b").struct.field("cell").str.contains(f"_(s{s[1]})_"))
            n_att, n_int, ir = _int_rate(sub)
            out[(s,)] = {"n": len(sub), "n_att": n_att, "n_int": n_int,
                         "int_rate": ir, "epa_mean": _epa_mean(sub)}
        return out


class QuarterSplit:
    """Marginal quarter cells (INT-grid component)."""

    name = "quarter"
    dimensions = ("q",)

    def compute(self, frame: pl.DataFrame) -> dict:
        f = bucketize(frame)
        out: dict[tuple, dict] = {}
        for q in ("q1", "q2", "q3", "q4"):
            sub = f.filter(pl.col("_b").struct.field("cell").str.contains(f"_(q{q[1]})_"))
            n_att, n_int, ir = _int_rate(sub)
            out[(q,)] = {"n": len(sub), "n_att": n_att, "n_int": n_int,
                         "int_rate": ir, "epa_mean": _epa_mean(sub)}
        return out


#: Registry of c02 split specs (mirrors c01's SPLIT_REGISTRY convention if any).
SPLIT_SPECS: dict[str, object] = {
    s.name: s for s in (
