# Provenance: reasoning-depth-spec.md §7 (analyze pipeline: escalate through levels
# as triggers fire; published pick/card MUST be L5 with breaking_conditions_met
# false and adversarial report attached), §4 (escalation triggers), §2.6 (trace
# persistence/resume), §8 T7 (resume, don't restart). The L4 review is c08's
# adversarial layer (adversary.py: adversary_review, killed_legs); checklist
# validator c08's checklist.py (validate_checklist). Shared types: schemas.py.

"""Analysis engine: analyze(req, ctx) → ReasoningTrace.

Pipeline: L1 → L2 → L3 (chains on trace) → escalation check → L4 (checklist +
c08 adversary review) → escalation check → L5 (synthesis). Traces persist to
the store keyed by content hash and can be resumed by merging new levels (T7).
"""

from __future__ import annotations

import uuid

from . import adversary as _adv
from . import checklist as _chk
from .enums import ChecklistVerdict, ReasoningDepth
from .escalation import (
    EscalationSignal,
    checklist_conflict_count,
    count_weak_links,
    escalate_to,
    next_depth,
)
from .exceptions import ChecklistInvalid, ContractViolation, InvalidDepth
from .interfaces import AnalysisRequest, DataContext
from .levels import (
    build_checklist,
    run_l1,
    run_l2,
    run_l3,
    run_l5_synthesis,
)
from .schemas import ReasoningTrace
from .specialists import SpecialistRegistry
from .trace import TraceStore, log_escalation, utcnow


class AnalysisEngine:
    def __init__(self, store_dir: str = "/tmp/gse-traces",
                 registry: SpecialistRegistry | None = None):
        self.store = TraceStore(store_dir)
        self.registry = registry or SpecialistRegistry()

    # -- trace lifecycle ---------------------------------------------------

    def new_trace(self, req: AnalysisRequest) -> ReasoningTrace:
        stamp = utcnow().replace(":", "").replace("+", "Z")
        return ReasoningTrace(
            trace_id=f"{stamp}-{uuid.uuid4().hex[:8]}",
            question=req.question,
            depth=ReasoningDepth.L1,
            exposure=req.exposure,
            game={"away": req.game.away, "home": req.game.home,
                  "week": req.game.week, "season": req.game.season},
            created_at=utcnow(),
        )

    # -- main pipeline -----------------------------------------------------

    def analyze(self, req: AnalysisRequest, ctx: DataContext) -> ReasoningTrace:
        if req.requested_depth is not None and not isinstance(
            req.requested_depth, ReasoningDepth
        ):
            raise InvalidDepth(f"requested_depth must be ReasoningDepth, got {req.requested_depth!r}")

        trace = (
            self.store.load(req.resume_trace_id)
            if req.resume_trace_id
            else self.new_trace(req)
        )
        trace.exposure = req.exposure

        # A resumed trace must still honor the depth contract: a card or
        # published pick below L5 is a contract violation, never a quiet pass.
        floor = self._effective_floor(req)
        if floor is not None and floor.rank() > trace.depth.rank():
            escalate_to(trace, floor, self._floor_trigger_name(req))

        # L1 — direct lookup.
        triggers = run_l1(req, ctx, trace, self.registry)
        if trace.depth == ReasoningDepth.L1:
            log_escalation(trace, ReasoningDepth.L1, ReasoningDepth.L1, "level_complete")
            self._maybe_escalate(trace, ReasoningDepth.L1, triggers, req, ctx)
        if trace.depth == ReasoningDepth.L1 and self._effective_floor(req) is None:
            return self._finalize(trace)

        # L2 — correlation.
        self._run_at(trace, req, ctx, ReasoningDepth.L2, lambda: run_l2(req, ctx, trace, self.registry))
        if trace.depth == ReasoningDepth.L2 and self._effective_floor(req) is None:
            return self._finalize(trace)

        # L3 — causal chains on the trace.
        def _l3():
            return run_l3(req, ctx, trace, self.registry)[0]

        self._run_at(trace, req, ctx, ReasoningDepth.L3, _l3)

        # L4 — checklist + adversary (the adversarial layer is c08's).
        if trace.depth.is_at_least(ReasoningDepth.L4):
            self._run_l4(req, ctx, trace)
            # Post-L4 escalation re-check: the completed L4 can fire L4 → L5
            # triggers (three_plus_legs, thesis_survived, two_plus_conflicts).
            # Without this, a genuine L3 → L4 walk never reaches L5. Added
            # 2026-10-02 during contract convergence (the provider façade's
            # pinned T3 behavior requires it).
            if trace.depth == ReasoningDepth.L4:
                self._maybe_escalate(trace, ReasoningDepth.L4, set(), req, ctx)

        # L5 — synthesis.
        if trace.depth == ReasoningDepth.L5:
            if trace.adversary_report is None:
                self._run_l4(req, ctx, trace)  # ensure the report exists
            run_l5_synthesis(trace, trace.adversary_report)

        return self._finalize(trace)

    def _effective_floor(self, req: AnalysisRequest) -> ReasoningDepth | None:
        """The depth the trace must reach: the requested floor, raised to L5
        when the exposure contract demands it (spec §7: a published pick or
        multi-leg card MUST be L5)."""
        floor = req.requested_depth
        if req.exposure.requires_l5():
            if floor is None or ReasoningDepth.L5.rank() > floor.rank():
                return ReasoningDepth.L5
        return floor

    def _run_at(self, trace, req, ctx, depth, runner):
        if depth.value not in trace.levels and trace.depth.is_at_least(depth):
            triggers = runner()
            log_escalation(trace, depth, depth, "level_complete")
            if trace.depth.value == depth.value:
                # Genuine walk (not a jump replay): triggers may escalate further.
                self._maybe_escalate(trace, depth, triggers, req, ctx)
            # Jump replay: payload only — the depth is already higher.

    def _floor_trigger_name(self, req: AnalysisRequest) -> str:
        if (
            req.exposure.requires_l5()
            and (req.requested_depth is None
                 or req.requested_depth.rank() < ReasoningDepth.L5.rank())
        ):
            return "exposure_requires_l5"
        return "requested_depth_floor"

    def _maybe_escalate(self, trace, depth, triggers, req, ctx):
        floor = self._effective_floor(req)
        if floor is not None and ReasoningDepth.ordered().index(floor) > ReasoningDepth.ordered().index(depth):
            escalate_to(trace, floor, self._floor_trigger_name(req))
            return
        signal = EscalationSignal(
            depth=depth,
            triggers=set(triggers),
            market_edge_pct=req.market_edge_pct,
            checklist_conflicts=(
                checklist_conflict_count(trace.checklist)
                if trace.checklist else 0
            ),
            weak_links=count_weak_links(trace),
            legs=len(req.legs),
        )
        # Request-derived triggers (spec §4 escalation summary: "bet requested,
        # causal claim made, or signal conflict" escalates L2 → L3; a bet
        # request implies a matchup for L1 → L2). Added 2026-10-02 during
        # contract convergence — the provider façade's bet requests must drive
        # escalation the same way the old integration layer did.
        if req.legs:
            signal.triggers.add("bet_requested")
            if depth == ReasoningDepth.L1:
                signal.triggers.add("matchup")
        # Exposure-driven triggers (spec §4 / §7 contract).
        if depth == ReasoningDepth.L3:
            if req.exposure.requires_l5():
                signal.triggers.add("real_exposure")
            if req.market_edge_pct and abs(req.market_edge_pct) > 5.0:
                signal.triggers.add("market_contradiction")
        if depth == ReasoningDepth.L4:
            if req.legs and len(req.legs) >= 3:
                signal.triggers.add("three_plus_legs")
            if req.exposure.requires_l5():
                signal.triggers.add("thesis_survived")
        target, trigger = next_depth(signal)
        if target is not None:
            escalate_to(trace, target, trigger)

    def _run_l4(self, req, ctx, trace):
        # No-blind-spots checklist (T2: gaps stay DATA-GAP).
        built = build_checklist(ctx, ReasoningDepth.L4)
        trace.checklist = {t: v for t, v in built.items()}
        gate = _chk.validate_checklist(trace)
        if not gate.valid:
            raise ChecklistInvalid(
                f"checklist gate rejected trace at L4: {gate.invalid_reason}",
                invalid_tracks=[
                    t for t in gate.verdicts
                    if gate.verdicts[t] == ChecklistVerdict.UNCHECKED
                ],
            )
        trace.levels[ReasoningDepth.L4.value] = {
            "checklist": {t: v.value for t, v in built.items()}
        }
        # The adversarial layer reads legs + chains + observed_values from the
        # trace (c08 adversary.py: adversary_review(trace)).
        trace.legs = list(req.legs)
        trace.observed_values = dict(ctx.observations)
        trace.track_evidence = dict(ctx.track_evidence)
        report = _adv.adversary_review(trace)
        trace.adversary_report = report
        trace.levels[ReasoningDepth.L4.value]["adversary"] = {
            "breaking_conditions_met": report.breaking_conditions_met,
            "correlated_theses": len(report.correlated_theses),
            "killed_thesis_ids": report.killed_thesis_ids,
        }
        log_escalation(trace, trace.depth, trace.depth, "adversary_review_complete")

    def _finalize(self, trace: ReasoningTrace) -> ReasoningTrace:
        # Defensive contract check (spec §7): a published pick or multi-leg
        # card below L5 is a contract violation — surfaced loudly, never silent.
        if not _chk.depth_contract_ok(trace.depth, trace.exposure):
            raise ContractViolation(
                f"depth contract violated: {trace.exposure.value} at {trace.depth.value}, "
                "published picks and cards MUST be L5"
            )
        trace.content_hash = self.store.save(trace)
        return trace


def analyze(req: AnalysisRequest, ctx: DataContext,
            store_dir: str = "/tmp/gse-traces") -> ReasoningTrace:
    return AnalysisEngine(store_dir=store_dir).analyze(req, ctx)

# Provenance: reasoning-depth-spec.md §4 (reasoning levels, escalation triggers,
# escalation summary table, "skipping levels is a logged exception, never silent"),
# §5 (CONFLICT auto-escalates to L4; 2+ CONFLICT → L5 required), §8 T3 (escalation
# triggers fire). Shared types from schemas.py (canonical contract).

"""Escalation state machine.

Depth is a property of the analysis with mandatory escalation triggers. The machine
evaluates triggers after each level and records every transition in the trace's
escalation_log. Skipping levels is permitted only as a logged exception.
De-escalation is refused outright.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from .enums import ChecklistVerdict, ReasoningDepth
from .schemas import ReasoningTrace
from .trace import log_escalation


# ---------------------------------------------------------------------------
# Triggers (spec §4 escalation summary)
# ---------------------------------------------------------------------------

TRIGGER_L1_TO_L2 = {"matchup", "line_vs_number", "injury_flag"}
TRIGGER_L2_TO_L3 = {"bet_requested", "causal_claim", "signal_conflict"}
TRIGGER_L3_TO_L4 = {"real_exposure", "market_contradiction", "weak_link"}
TRIGGER_L4_TO_L5 = {
    "thesis_survived",
    "three_plus_legs",
    "full_picture",
    "exposure_requires_l5",  # spec §7 contract: published pick/card MUST be L5
}


@dataclass
class EscalationSignal:
    """What the pipeline observed at a level boundary."""

    depth: ReasoningDepth
    triggers: set[str] = field(default_factory=set)
    market_edge_pct: float = 0.0
    checklist_conflicts: int = 0
    weak_links: int = 0
    legs: int = 0


def next_depth(signal: EscalationSignal) -> tuple[ReasoningDepth | None, str | None]:
    """Return (target_depth, trigger_name) or (None, None).

    Fires the highest applicable target — e.g. 2+ CONFLICT tracks force L5
    regardless of leg count (spec §5).
    """
    t = signal.triggers

    if signal.checklist_conflicts >= 2:
        return ReasoningDepth.L5, "two_plus_conflicts"

    if signal.depth == ReasoningDepth.L1 and t & TRIGGER_L1_TO_L2:
        return ReasoningDepth.L2, sorted(t & TRIGGER_L1_TO_L2)[0]
    if signal.depth == ReasoningDepth.L2 and t & TRIGGER_L2_TO_L3:
        return ReasoningDepth.L3, sorted(t & TRIGGER_L2_TO_L3)[0]
    if signal.depth == ReasoningDepth.L3:
        if "real_exposure" in t:
            return ReasoningDepth.L4, "real_exposure"
        if "market_contradiction" in t and abs(signal.market_edge_pct) > 5.0:
            return ReasoningDepth.L4, "market_contradiction"
        if "weak_link" in t or signal.weak_links > 0:
            return ReasoningDepth.L4, "weak_link"
    if signal.depth == ReasoningDepth.L4 and t & TRIGGER_L4_TO_L5:
        return ReasoningDepth.L5, sorted(t & TRIGGER_L4_TO_L5)[0]
    return None, None


def escalate_to(
    trace: ReasoningTrace, target: ReasoningDepth, trigger: str
) -> None:
    """Move the trace to `target`, logging every intermediate level.

    Multi-level jumps log each skipped level as skipped=True — a logged
    exception, never silent. De-escalation raises.
    """
    ordered = ReasoningDepth.ordered()
    cur, tgt = ordered.index(trace.depth), ordered.index(target)
    if tgt < cur:
        raise ValueError(f"refusing silent de-escalation {trace.depth.value} → {target.value}")
    for i in range(cur, tgt):
        nxt = ordered[i + 1]
        skipped = (tgt - cur) > 1 and nxt != target
        log_escalation(trace, ordered[i], nxt, trigger, skipped=skipped)
    trace.depth = target  # the only place depth moves on escalation


def checklist_conflict_count(checklist: dict[str, ChecklistVerdict]) -> int:
    return sum(1 for v in checklist.values() if v == ChecklistVerdict.CONFLICT)


def count_weak_links(trace: ReasoningTrace) -> int:
    """Chains with a load-bearing INFERENCE/SINGLE_SOURCE link (spec §8 T5)."""
    from .enums import Verification

    n = 0
    for chain in trace.chains:
        for link in chain.links:
            if (
                link.load_bearing
                and link.verification in (Verification.INFERENCE, Verification.SINGLE_SOURCE)
            ):
                n += 1
                break
    return n

# Provenance: reasoning-depth-spec.md §4 (L1–L5 level definitions and outputs),
# §5 (five mandatory tracks; Garrett's hierarchy OL → scheme → QB in L5 synthesis,
# §8 T6), §2.2 (specialists run in parallel; synthesizer sequential after them),
# §2.5 (trace is the unit of coherence). Shared types from schemas.py; the L4
# review is c08's adversary.py (adversary_review, killed_legs).

"""Level runners L1–L5.

Each runner executes its level's specialists and writes into the trace. The L5
synthesizer consumes c08's AdversaryReport and honors the killed-legs contract:
legs of KILL-verdict theses are never recommended.
"""

from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor

from . import adversary as _adv
from .enums import TRACKS, ChecklistVerdict, ReasoningDepth, Verification
from .interfaces import AnalysisRequest, DataContext, SpecialistOutput
from .schemas import ReasoningTrace
from .specialists import SpecialistRegistry


def run_specialists_parallel(
    depth: ReasoningDepth,
    req: AnalysisRequest,
    ctx: DataContext,
    trace: ReasoningTrace,
    registry: SpecialistRegistry,
    max_workers: int = 5,
) -> list[SpecialistOutput]:
    """Run all specialists concurrently (spec §2.2, §2.4)."""
    specialists = registry.all()
    with ThreadPoolExecutor(max_workers=max_workers or len(specialists)) as pool:
        futures = [pool.submit(s.run, depth, req, ctx, trace) for s in specialists]
        return [f.result() for f in futures]


def _collect_triggers(outputs: list[SpecialistOutput]) -> set[str]:
    triggers: set[str] = set()
    for o in outputs:
        triggers |= o.triggers
    return triggers


def run_l1(req, ctx, trace, registry) -> set[str]:
    """L1 — direct lookup: value + source pointer + verification status."""
    outputs = run_specialists_parallel(ReasoningDepth.L1, req, ctx, trace, registry)
    claims = [c for o in outputs for c in o.claims]
    trace.levels[ReasoningDepth.L1.value] = {
        "claims": [
            {"text": c.text, "verification": c.verification.value,
             "source": c.source, "value": c.value, "note": c.note}
            for c in claims
        ]
    }
    return _collect_triggers(outputs)


def run_l2(req, ctx, trace, registry) -> set[str]:
    """L2 — cross-stat correlation: findings + which are computed vs asserted."""
    outputs = run_specialists_parallel(ReasoningDepth.L2, req, ctx, trace, registry)
    correlations = [c for o in outputs for c in o.correlations]
    trace.levels[ReasoningDepth.L2.value] = {"correlations": correlations}
    triggers = _collect_triggers(outputs)
    # Causal-language scan (spec §4: "a causal claim" in L2 escalates to L3).
    # Scans specialist claims AND the analysis question itself — a question like
    # "will pressure overwhelm the OL?" IS the causal claim L2 must address.
    # (Question scanning added 2026-10-02 during contract convergence; the
    # question word list mirrors the provider façade's pinned behavior.)
    claim_texts = [c.text for o in outputs for c in o.claims]
    if any(w in t.lower() for t in claim_texts
           for w in ("will overwhelm", "will cause", "because")):
        triggers.add("causal_claim")
    q = (req.question or "").lower()
    if any(w in q for w in ("because", "lead to", "leads to", "caus",
                            "->", "→", "overwhelm", "neutraliz")):
        triggers.add("causal_claim")
    return triggers


# Garrett's hierarchy for L5 synthesis evaluation order (spec §8 T6):
# OL → scheme → QB. The T6 constraint: index(OL) < index(coaching_scheme) < index(qb_behavior).
HIERARCHY_ORDER: list[str] = [
    "offensive_line",
    "coaching_scheme",
    "scheme_matchup",
    "qb_behavior",
    "trust_signals",
]


def check_hierarchy(trace: ReasoningTrace) -> bool:
    """T6: the L5 synthesis must show OL evaluated before scheme, scheme before QB."""
    order = trace.hierarchy_order or HIERARCHY_ORDER
    try:
        return (
            order.index("offensive_line")
            < order.index("coaching_scheme")
            < order.index("qb_behavior")
        )
    except ValueError:
        return False


def run_l3(req, ctx, trace, registry) -> tuple[set[str], list]:
    """L3 — causal chains live on the trace (trace.chains), each link sourced.

    Chains arrive via the DataContext (built by the wiring layer / fixtures) and
    specialist outputs. INFERENCE/SINGLE_SOURCE load-bearing links are flagged
    via the weak_link trigger (spec §8 T5).
    """
    outputs = run_specialists_parallel(ReasoningDepth.L3, req, ctx, trace, registry)
    seen = {c.id for c in trace.chains}
    for c in ctx.chains:  # wired chains land on the trace (the unit the adversary attacks)
        if c.id not in seen:
            trace.chains.append(c)
            seen.add(c.id)
    for o in outputs:
        for c in o.chains:
            if c.id not in seen:
                trace.chains.append(c)
                seen.add(c.id)
    trace.levels[ReasoningDepth.L3.value] = {"chain_ids": [c.id for c in trace.chains]}
    triggers = _collect_triggers(outputs)
    for chain in trace.chains:
        for link in chain.links:
            if (
                link.load_bearing
                and link.verification in (Verification.INFERENCE, Verification.SINGLE_SOURCE)
            ):
                triggers.add("weak_link")
    for o in outputs:
        if o.conflicts_with:
            triggers.add("signal_conflict")
    return triggers, trace.chains


def build_checklist(ctx: DataContext, depth: ReasoningDepth) -> dict[str, ChecklistVerdict]:
    """Build the no-blind-spots checklist (spec §5).

    Verdicts come from ctx.checklist_hints. Tracks with no hint and no data at L3+
    become DATA-GAP (T2: a track with no data is DATA-GAP, not UNCHECKED, not
    silent). Below L3, unhinted tracks are UNCHECKED (valid there).
    """
    verdicts: dict[str, ChecklistVerdict] = {}
    for track in TRACKS:
        hint = ctx.checklist_hints.get(track)
        if hint:
            verdicts[track] = ChecklistVerdict(hint)
        elif depth.is_at_least(ReasoningDepth.L3):
            verdicts[track] = ChecklistVerdict.DATA_GAP
        else:
            verdicts[track] = ChecklistVerdict.UNCHECKED
    return verdicts


def run_l5_synthesis(trace: ReasoningTrace, report) -> dict:
    """L5 — synthesis honoring Garrett's hierarchy and the killed-legs contract.

    Legs of KILL-verdict theses are excluded from any recommendation (spec §8 T1:
    the funnel stack must NOT be recommended). Only L5 may produce a
    public-facing pick or card.
    """
    trace.hierarchy_order = list(HIERARCHY_ORDER)
    if not check_hierarchy(trace):
        raise ValueError("L5 synthesis hierarchy violated: OL → scheme → QB order broken")

    killed = _adv.killed_legs(report)
    bundles = report.correlated_theses

    if killed:
        multi = [b for b in bundles if len(b.leg_ids) > 1]
        if multi:
            b = multi[0]
            links = ", ".join(b.shared_link_ids) or "shared causal link"
            recommendation = (
                f"REJECT stack {b.leg_ids} as ONE correlated thesis on '{links}'. "
                "The legs share a single causal link whose falsifiers are already "
                "observed pre-kickoff — presenting them as independent edges would "
                "misstate exposure. Killed legs are excluded from any recommendation."
            )
        else:
            recommendation = (
                f"REJECT legs {killed}: their breaking conditions are met in "
                "pre-kickoff observations. No independent edge survives the adversary."
            )
    elif report.breaking_conditions_met:
        recommendation = (
            "REJECT the recommended legs: breaking conditions are met in pre-kickoff "
            "observations. No independent edge survives the adversary."
        )
    else:
        recommendation = (
            "Thesis survived L4 adversary (no breaking condition met). Proceed only "
            "with the checklist verdicts and weak-link flags attached; final sizing "
            "and publication remain downstream gates."
        )

    payload = {
        "recommendation": recommendation,
        "killed_legs": killed,
        "hierarchy_order": trace.hierarchy_order,
        "hierarchy_ok": True,
        "checklist": {t: v.value for t, v in trace.checklist.items()},
        "adversary": {
            "breaking_conditions_met": report.breaking_conditions_met,
            "condition_results": [
                {"condition_id": r.condition_id, "text": r.text, "metric": r.metric,
                 "observed_value": r.observed_value, "verifiable": r.verifiable, "met": r.met}
                for r in report.condition_results
            ],
            "correlated_theses": [
                {"id": b.id, "leg_ids": b.leg_ids, "shared_link_ids": b.shared_link_ids}
                for b in bundles
            ],
            "thesis_verdicts": report.thesis_verdicts,
            "killed_thesis_ids": report.killed_thesis_ids,
            "counter_argument": report.counter_argument,
            "pre_mortem": report.pre_mortem,
            "weak_link": report.weak_link,
            "weak_links": [
                {"link_id": w.link_id, "verification": w.verification.value,
                 "breaking_condition_present": w.breaking_condition_present,
                 "breaking_condition_machine_checkable": w.breaking_condition_machine_checkable}
                for w in report.weak_links
            ],
            "gap_assumptions": [
                {"track": g.track, "assumed_value": g.assumed_value, "rationale": g.rationale}
                for g in report.gap_assumptions
            ],
            "notes": report.notes,
        },
    }
    trace.levels[ReasoningDepth.L5.value] = payload
    trace.label = "FINAL"
    return payload

# Provenance: reasoning-depth-spec.md §2.2 (five specialist agents; the adversary
# specialist is a separate context with the explicit job of falsification), §2.4
# (specialists invoke data tools, not vibes; tool calls recorded), §7 (API shape).
# Shared types from schemas.py (canonical contract).

"""Specialist agents.

The five specialists run in parallel at each level (spec §2.2). They are
data-driven: every claim they emit must come from the DataContext (profiles,
market, observations, tool backend) — never invented. The registry lets callers
replace or extend specialists without touching the engine.
"""

from __future__ import annotations

from typing import Callable, Protocol

from .enums import ReasoningDepth, Verification
from .interfaces import AnalysisRequest, DataContext, SpecialistOutput
from .schemas import Claim
from .trace import record_tool_call


class BaseSpecialist:
    name = "base"

    def claim(self, text, verification, source="", value=None, note=""):  # noqa: ANN001, ANN202
        return Claim(text=text, verification=verification, source=source, value=value, note=note)

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:  # noqa: ANN001, ANN202
        return SpecialistOutput(agent=self.name)


class Specialist(Protocol):
    name: str

    def run(self, depth: ReasoningDepth, req: AnalysisRequest,  # noqa: ANN202
            ctx: DataContext, trace) -> SpecialistOutput: ...


class StatSpecialist(BaseSpecialist):
    """Numbers: lines, splits, rates, market data."""

    name = "stat"

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:
        out = SpecialistOutput(agent=self.name)
        for key, val in ctx.market.items():
            out.claims.append(self.claim(
                f"market {key} = {val}", Verification.CORPUS, source="market feed", value=val))
            record_tool_call(trace, "market_lookup", {"key": key}, str(val))
        for key, val in ctx.observations.items():
            if key.startswith("stat."):
                out.claims.append(self.claim(
                    f"{key} = {val}", Verification.CORPUS, source="observations", value=val))
        if depth.is_at_least(ReasoningDepth.L2):
            out.triggers.add("matchup")
        return out


class SchemeSpecialist(BaseSpecialist):
    """Coaching/scheme layer: tendencies, adjustments, YoY deltas."""

    name = "scheme"

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:
        out = SpecialistOutput(agent=self.name)
        for key, val in ctx.profiles.items():
            if key.startswith("coach."):
                out.claims.append(self.claim(
                    f"coaching profile {key}: {val}", Verification.CORPUS,
                    source=f"profile:{key}", value=val))
                record_tool_call(trace, "profile_lookup", {"coach": key}, str(val))
        for key, val in ctx.observations.items():
            if key.startswith("scheme."):
                out.claims.append(self.claim(
                    f"{key} = {val}", Verification.COMPUTED,
                    source="coaching-tendencies pipeline", value=val,
                    note="computed from nflverse play data"))
        return out


class BehaviorSpecialist(BaseSpecialist):
    """QB behavioral profiles: pressure splits, trust targets, scramble triggers."""

    name = "behavior"

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:
        out = SpecialistOutput(agent=self.name)
        for key, val in ctx.profiles.items():
            if key.startswith("qb."):
                out.claims.append(self.claim(
                    f"QB profile {key}: {val}", Verification.CORPUS,
                    source=f"profile:{key}", value=val))
                record_tool_call(trace, "profile_lookup", {"qb": key}, str(val))
        return out


class SignalSpecialist(BaseSpecialist):
    """Trust signals / news intake: social, video, injury reports."""

    name = "signal"

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:
        out = SpecialistOutput(agent=self.name)
        for sig in ctx.live_signals:
            out.claims.append(self.claim(
                f"live signal: {sig}", Verification.SINGLE_SOURCE,
                source="trust-signal intake", note="single-source until corroborated"))
        if any("injur" in s.lower() for s in ctx.live_signals):
            out.triggers.add("injury_flag")
        return out


class AdversarySpecialist(BaseSpecialist):
    """Falsification-oriented claims at L3+.

    This specialist *emits* adversarial claims during level runs. The full L4
    adversary *review* is the c08 adversarial layer (adversary.py).
    """

    name = "adversary"

    def run(self, depth, req, ctx, trace) -> SpecialistOutput:
        out = SpecialistOutput(agent=self.name)
        if depth.is_at_least(ReasoningDepth.L3):
            for chain in trace.chains:
                for link in chain.links:
                    for cond in link.breaking_conditions:
                        out.claims.append(self.claim(
                            f"falsifier for link {link.id}: {cond.text}",
                            Verification.INFERENCE, source="adversary specialist",
                            note="breaking condition checked against observed_values"))
        return out


DEFAULT_SPECIALISTS: list[BaseSpecialist] = [
    StatSpecialist(), SchemeSpecialist(), BehaviorSpecialist(),
    SignalSpecialist(), AdversarySpecialist(),
]


class SpecialistRegistry:
    def __init__(self, specialists: list[BaseSpecialist] | None = None):
        self._specialists = list(specialists) if specialists else list(DEFAULT_SPECIALISTS)

    def register(self, specialist: BaseSpecialist) -> None:
        self._specialists = [s for s in self._specialists if s.name != specialist.name]
        self._specialists.append(specialist)

    def all(self) -> list[BaseSpecialist]:
        return list(self._specialists)


