#!/usr/bin/env python3
"""Wave-2 wiring worker: INGEST slice 1 generator.

Reads ~/workspace/wiring-wave2/slice-INGEST-1.json (136 records) and emits, per
record, one TypeScript module + one vitest test file into
~/workspace/vendor/Sports/packages/data-ingestion/src/.

Filename: <arxiv-slug>-<lane>.ts  (arxiv-slug = arxiv_id with '.' -> '-').
The slug is unique per record, so no collisions across workers.
"""
import json
import os
import re
import sys

SLICE = "/home/hatch/workspace/wiring-wave2/slice-INGEST-1.json"
OUTDIR = "/home/hatch/workspace/vendor/Sports/packages/data-ingestion/src"

GUARD = '''/** Numeric guard: rejects NaN, Infinity, and non-numbers. */
function isFiniteNumber(x: unknown): x is number {
  return typeof x === "number" && Number.isFinite(x);
}
'''

MEAN_STD = '''
/** Population mean, or null on empty/malformed input. */
function mean(xs: readonly number[]): number | null {
  if (xs.length === 0 || !xs.every(isFiniteNumber)) return null;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

/** Population standard deviation, or null on empty/malformed input. */
function std(xs: readonly number[]): number | null {
  const m = mean(xs);
  if (m === null) return null;
  return Math.sqrt(xs.reduce((a, v) => a + (v - m) * (v - m), 0) / xs.length);
}

/** Sample variance (n-1), or null on <2 points/malformed input. */
function sampleVariance(xs: readonly number[]): number | null {
  if (xs.length < 2 || !xs.every(isFiniteNumber)) return null;
  const m = xs.reduce((a, b) => a + b, 0) / xs.length;
  return xs.reduce((a, v) => a + (v - m) * (v - m), 0) / (xs.length - 1);
}
'''

# ---------------------------------------------------------------- lane bodies
# Each entry: mechanism (1-3 lines for the JSDoc), ingest_role, config literal
# (TS object body without braces), module_ts (shared pure functions),
# test_ts (vitest assertions, uses %%FILE%% / %%ARXIV%% tokens).
LANES = {}

LANES["active_learning"] = {
    "mechanism": (
        "Average-case active learning under labeling costs: rank pool candidates by expected model "
        "improvement per unit cost, score(x) = Delta(x)/c(x), and acquire greedily by that ratio instead "
        "of cost-blind uncertainty sampling; batch costs are subadditive because setup/context is shared. "
        "Market-implied game importance acts as the prior over which games matter."
    ),
    "ingest_role": "charting-acquisition prioritization (info-per-cost ranking + subadditive batch costing)",
    "config": 'enabled: false,\n  method: "information-per-unit-cost greedy acquisition",\n  batchSize: 16,\n  costSharing: 0.25,',
    "module": GUARD + '''
export interface AcquisitionCandidate {
  id: string;
  /** Expected model improvement from charting this game (gradient-norm / MI leverage proxy). */
  delta: number;
  /** Acquisition cost in charting dollars/minutes. Must be > 0. */
  cost: number;
  /** Market-implied prior weight for game importance. Defaults to 1. */
  gameImportance?: number;
}

function validCandidate(c: AcquisitionCandidate): boolean {
  return (
    typeof c.id === "string" &&
    c.id.length > 0 &&
    isFiniteNumber(c.delta) &&
    c.delta >= 0 &&
    isFiniteNumber(c.cost) &&
    c.cost > 0 &&
    (c.gameImportance === undefined || (isFiniteNumber(c.gameImportance) && c.gameImportance >= 0))
  );
}

/**
 * Information-per-unit-cost score: score(x) = Delta(x) * importance / c(x).
 * Returns null on malformed input (fail-closed).
 */
export function infoPerCostScore(delta: number, cost: number, gameImportance = 1): number | null {
  if (!isFiniteNumber(delta) || delta < 0) return null;
  if (!isFiniteNumber(cost) || cost <= 0) return null;
  if (!isFiniteNumber(gameImportance) || gameImportance < 0) return null;
  return (delta * gameImportance) / cost;
}

/**
 * Greedy acquisition by Delta/c ratio under a dollar budget (replaces cost-blind greedy).
 * Returns selected ids in acquisition order plus totals, or null on malformed input.
 */
export function greedyAcquireByRatio(
  candidates: readonly AcquisitionCandidate[],
  budget: number,
): { selected: string[]; totalCost: number; totalDelta: number } | null {
  if (!isFiniteNumber(budget) || budget < 0) return null;
  if (!candidates.every(validCandidate)) return null;
  const scored = candidates
    .map((c) => ({ c, score: infoPerCostScore(c.delta, c.cost, c.gameImportance ?? 1) ?? 0 }))
    .sort((a, b) => b.score - a.score);
  const selected: string[] = [];
  let totalCost = 0;
  let totalDelta = 0;
  for (const { c } of scored) {
    if (totalCost + c.cost <= budget) {
      selected.push(c.id);
      totalCost += c.cost;
      totalDelta += c.delta * (c.gameImportance ?? 1);
    }
  }
  return { selected, totalCost, totalDelta };
}

/**
 * Subadditive batch cost model: charting a batch costs less than the sum of individual
 * costs because setup/context is shared. cost(batch) = max + (1 - sharing) * (sum - max),
 * always <= sum for sharing in [0, 1].
 */
export function subadditiveBatchCost(costs: readonly number[], sharing = 0.25): number | null {
  if (costs.length === 0) return null;
  if (!costs.every((c) => isFiniteNumber(c) && c >= 0)) return null;
  if (!isFiniteNumber(sharing) || sharing < 0 || sharing > 1) return null;
  const sum = costs.reduce((a, b) => a + b, 0);
  const max = Math.max(...costs);
  return max + (1 - sharing) * (sum - max);
}
''',
    "test": '''import { describe, expect, it } from "vitest";
import * as mod from "./%%FILE%%";

describe("info-per-cost active learning (arXiv:%%ARXIV%%)", () => {
  it("scores delta over cost", () => {
    expect(mod.infoPerCostScore(10, 5)).toBeCloseTo(2, 10);
    expect(mod.infoPerCostScore(10, 5, 2)).toBeCloseTo(4, 10);
    expect(mod.infoPerCostScore(10, 0)).toBeNull();
    expect(mod.infoPerCostScore(-1, 5)).toBeNull();
    expect(mod.infoPerCostScore(10, 5, -1)).toBeNull();
  });

  it("greedy acquisition by ratio under a budget", () => {
    const cands = [
      { id: "a", delta: 10, cost: 5 },
      { id: "b", delta: 6, cost: 4 },
      { id: "c", delta: 9, cost: 3 },
    ];
    const r = mod.greedyAcquireByRatio(cands, 8)!;
    expect(r.selected).toEqual(["c", "a"]);
    expect(r.totalCost).toBe(8);
    expect(r.totalDelta).toBe(19);
    expect(mod.greedyAcquireByRatio(cands, -1)).toBeNull();
    expect(mod.greedyAcquireByRatio([{ id: "x", delta: 1, cost: 0 }], 8)).toBeNull();
  });

  it("subadditive batch cost stays below the sum of parts", () => {
    const c = mod.subadditiveBatchCost([5, 5], 0.25)!;
    expect(c).toBeCloseTo(8.75, 10);
    expect(c).toBeLessThanOrEqual(10);
    expect(mod.subadditiveBatchCost([5], 0.25)).toBeCloseTo(5, 10);
    expect(mod.subadditiveBatchCost([], 0.25)).toBeNull();
  });
});
''',
}

LANES["markets"] = {
    "mechanism": (
        "Racetrack-market efficiency diagnostics ported to NFL lines: bucket a spread/total line time "
        "series from open to close, track concentration (Herfindahl of side shares) and the average-vs-"
        "efficient return (AR/EAR) curves, and locate interior AR~EAR crossings - the timestamps where the "
        "market's read is most informative. A single monotonic path means the phenomenon does not transfer."
    ),
    "ingest_role": "market-efficiency diagnostics (efficiency-phase curves + crossing detection on line time series)",
    "config": 'enabled: false,\n  method: "AR/EAR efficiency-phase diagnostic on line time series",\n  minBuckets: 8,',
    "module": GUARD + '''
/**
 * Herfindahl concentration index of vote/handle shares. Ranges from 1/n (dispersed)
 * to 1 (fully concentrated). Null on malformed input.
 */
export function concentrationIndex(shares: readonly number[]): number | null {
  if (shares.length === 0) return null;
  if (!shares.every((s) => isFiniteNumber(s) && s >= 0)) return null;
  const total = shares.reduce((a, b) => a + b, 0);
  if (total <= 0) return null;
  return shares.reduce((a, s) => a + (s / total) * (s / total), 0);
}

/** Chronological bucket means of a time series (n contiguous buckets). */
export function bucketMeans(values: readonly number[], nBuckets: number): number[] | null {
  if (!Number.isInteger(nBuckets) || nBuckets <= 0) return null;
  if (values.length < nBuckets) return null;
  if (!values.every(isFiniteNumber)) return null;
  const out: number[] = [];
  const size = values.length / nBuckets;
  for (let b = 0; b < nBuckets; b++) {
    const lo = Math.floor(b * size);
    const hi = Math.max(Math.floor((b + 1) * size), lo + 1);
    const slice = values.slice(lo, hi);
    out.push(slice.reduce((a, v) => a + v, 0) / slice.length);
  }
  return out;
}

/**
 * Count AR~EAR crossings: sign changes of (a - b) between two equal-length series.
 * A non-monotonic concentration-dispersion-reconcentration path shows >= 1 interior crossing.
 */
export function countCrossings(a: readonly number[], b: readonly number[]): number | null {
  if (a.length !== b.length || a.length < 2) return null;
  if (!a.every(isFiniteNumber) || !b.every(isFiniteNumber)) return null;
  let crossings = 0;
  let prev = Math.sign((a[0] ?? 0) - (b[0] ?? 0));
  for (let i = 1; i < a.length; i++) {
    const s = Math.sign((a[i] ?? 0) - (b[i] ?? 0));
    if (s === 0) continue;
    if (prev === 0) {
      prev = s;
      continue;
    }
    if (s !== prev) crossings++;
    prev = s;
  }
  return crossings;
}

/** True when the series changes direction at least once (non-monotonic efficiency path). */
export function isNonMonotonicPath(values: readonly number[]): boolean | null {
  if (values.length < 3 || !values.every(isFiniteNumber)) return null;
  let dir = 0;
  for (let i = 1; i < values.length; i++) {
    const d = Math.sign((values[i] ?? 0) - (values[i - 1] ?? 0));
    if (d === 0) continue;
    if (dir !== 0 && d !== dir) return true;
    dir = d;
  }
  return false;
}
''',
    "test": '''import { describe, expect, it } from "vitest";
import * as mod from "./%%FILE%%";

describe("market efficiency diagnostics (arXiv:%%ARXIV%%)", () => {
  it("concentration index (Herfindahl)", () => {
    expect(mod.concentrationIndex([0.5, 0.5])).toBeCloseTo(0.5, 10);
    expect(mod.concentrationIndex([1, 0, 0, 0])).toBeCloseTo(1, 10);
    expect(mod.concentrationIndex([0.25, 0.25, 0.25, 0.25])).toBeCloseTo(0.25, 10);
    expect(mod.concentrationIndex([])).toBeNull();
    expect(mod.concentrationIndex([0.5, -0.5])).toBeNull();
  });

  it("chronological bucket means", () => {
    expect(mod.bucketMeans([1, 2, 3, 4], 2)).toEqual([1.5, 3.5]);
    expect(mod.bucketMeans([1, 2], 3)).toBeNull();
    expect(mod.bucketMeans([1, 2, 3], 0)).toBeNull();
  });

  it("counts AR~EAR crossings", () => {
    expect(mod.countCrossings([1, 3, 1], [2, 2, 2])).toBe(2);
    expect(mod.countCrossings([1, 2, 3], [4, 5, 6])).toBe(0);
    expect(mod.countCrossings([1], [2])).toBeNull();
    expect(mod.countCrossings([1, 2], [1])).toBeNull();
  });

  it("detects non-monotonic paths", () => {
    expect(mod.isNonMonotonicPath([1, 3, 2])).toBe(true);
    expect(mod.isNonMonotonicPath([1, 2, 3])).toBe(false);
    expect(mod.isNonMonotonicPath([1, 2])).toBeNull();
  });
});
''',
}

LANES["calibration"] = {
    "mechanism": (
        "Binned reliability analysis plus isotonic (PAVA) recalibration: group predicted probabilities "
        "into bins, measure expected calibration error as the count-weighted |observed - predicted| gap, "
        "and refit a monotone non-decreasing correction so recalibrated probabilities match empirical "
        "frequencies."
    ),
    "ingest_role": "probability calibration (reliability bins, ECE, isotonic recalibration)",
    "config": 'enabled: false,\n  method: "binned reliability + PAVA isotonic recalibration",\n  bins: 10,',
    "module": GUARD + '''
export interface ReliabilityBin {
  lo: number;
  hi: number;
  meanPred: number;
  meanObs: number;
  count: number;
}

function validPair(pr: { p: number; y: number }): boolean {
  return isFiniteNumber(pr.p) && pr.p >= 0 && pr.p <= 1 && (pr.y === 0 || pr.y === 1);
}

/** Group (p, y) pairs into nBins reliability bins over [0, 1]. */
export function binPredictions(
  pairs: ReadonlyArray<{ p: number; y: number }>,
  nBins: number,
): ReliabilityBin[] | null {
  if (!Number.isInteger(nBins) || nBins <= 0) return null;
  if (pairs.length === 0 || !pairs.every(validPair)) return null;
  const bins: ReliabilityBin[] = [];
  for (let b = 0; b < nBins; b++) {
    const lo = b / nBins;
    const hi = (b + 1) / nBins;
    const inBin = pairs.filter((pr) =>
      b === nBins - 1 ? pr.p >= lo && pr.p <= hi : pr.p >= lo && pr.p < hi,
    );
    bins.push({
      lo,
      hi,
      meanPred: inBin.length > 0 ? inBin.reduce((a, pr) => a + pr.p, 0) / inBin.length : (lo + hi) / 2,
      meanObs: inBin.length > 0 ? inBin.reduce((a, pr) => a + pr.y, 0) / inBin.length : 0,
      count: inBin.length,
    });
  }
  return bins;
}

/** Expected calibration error: count-weighted mean |observed - predicted| over bins. */
export function expectedCalibrationError(bins: ReadonlyArray<ReliabilityBin>): number | null {
  const total = bins.reduce((a, b) => a + b.count, 0);
  if (total <= 0) return null;
  return bins.reduce((a, b) => a + (b.count / total) * Math.abs(b.meanObs - b.meanPred), 0);
}

/**
 * Isotonic recalibration via pool-adjacent-violators (PAVA) on sorted predicted probabilities.
 * Returns fitted monotone non-decreasing values aligned with the sorted input order.
 */
export function isotonicCalibrate(pairs: ReadonlyArray<{ p: number; y: number }>): number[] | null {
  if (pairs.length === 0 || !pairs.every(validPair)) return null;
  const sorted = [...pairs].sort((a, b) => a.p - b.p);
  const blocks: Array<{ sum: number; count: number }> = [];
  for (const pr of sorted) {
    blocks.push({ sum: pr.y, count: 1 });
    while (blocks.length >= 2) {
      const n = blocks.length;
      const last = blocks[n - 1]!;
      const prev = blocks[n - 2]!;
      if (prev.sum / prev.count <= last.sum / last.count) break;
      blocks.pop();
      blocks.pop();
      blocks.push({ sum: prev.sum + last.sum, count: prev.count + last.count });
    }
  }
  const fitted: number[] = [];
  for (const b of blocks) {
    const v = b.sum / b.count;
    for (let i = 0; i < b.count; i++) fitted.push(v);
  }
  return fitted;
}
''',
    "test": '''import { describe, expect, it } from "vitest";
import * as mod from "./%%FILE%%";

describe("calibration diagnostics (arXiv:%%ARXIV%%)", () => {
  const pairs = [
    { p: 0.1, y: 0 },
    { p: 0.2, y: 0 },
    { p: 0.8, y: 1 },
    { p: 0.9, y: 1 },
  ];

  it("bins predictions into reliability bins", () => {
    const bins = mod.binPredictions(pairs, 2)!;
    expect(bins).toHaveLength(2);
    expect(bins[0]!.count).toBe(2);
    expect(bins[0]!.meanPred).toBeCloseTo(0.15, 10);
    expect(bins[0]!.meanObs).toBe(0);
    expect(bins[1]!.meanObs).toBe(1);
    expect(mod.binPredictions([], 2)).toBeNull();
    expect(mod.binPredictions(pairs, 0)).toBeNull();
  });

  it("computes expected calibration error", () => {
    const bins = mod.binPredictions(pairs, 2)!;
    // 0.5 * |0 - 0.15| + 0.5 * |1 - 0.85| = 0.15
    expect(mod.expectedCalibrationError(bins)).toBeCloseTo(0.15, 10);
    const perfect = mod.binPredictions(
      [
        { p: 0.2, y: 0 },
        { p: 0.2, y: 0 },
        { p: 0.8, y: 1 },
        { p: 0.8, y: 1 },
      ],
      2,
    )!;
    expect(mod.expectedCalibrationError(perfect)).toBeCloseTo(0.2, 10);
  });

  it("isotonic calibration is monotone non-decreasing", () => {
    const fitted = mod.isotonicCalibrate([
      { p: 0.1, y: 0 },
      { p: 0.2, y: 1 },
      { p: 0.3, y: 0 },
    ])!;
    expect(fitted).toEqual([0, 0.5, 0.5]);
    for (let i = 1; i < fitted.length; i++) {
      expect(fitted[i]!).toBeGreaterThanOrEqual(fitted[i - 1]!);
    }
    expect(mod.isotonicCalibrate([])).toBeNull();
  });
});
''',
}

LANES["props_dfs"] = {
    "mechanism": (
        "Salary-cap-constrained lineup construction as a 0/1 knapsack (exactly k players, maximize "
        "projected points under the cap), multi-source projection blending with normalized weights, and "
        "ownership-leverage scoring that discounts projections by expected roster percentage."
    ),
    "ingest_role": "DFS lineup construction primitives (knapsack optimizer, projection blending, leverage scoring)",
    "config": 'enabled: false,\n  method: "salary-cap knapsack lineup construction",',
    "module": GUARD + '''
export interface PlayerEntry {
  id: string;
  /** Integer salary cost. */
  salary: number;
  /** Projected fantasy points (>= 0). */
  proj: number;
}

function validPlayer(p: PlayerEntry): boolean {
  return (
    typeof p.id === "string" &&
    p.id.length > 0 &&
    Number.isInteger(p.salary) &&
    p.salary > 0 &&
    isFiniteNumber(p.proj) &&
    p.proj >= 0
  );
}

/**
 * 0/1 knapsack: pick exactly `slots` players maximizing projected points under the salary cap.
 * Returns null on malformed input or infeasible constraints.
 */
export function knapsackLineup(
  players: readonly PlayerEntry[],
  salaryCap: number,
  slots: number,
): { lineup: string[]; totalSalary: number; totalProj: number } | null {
  if (!Number.isInteger(salaryCap) || salaryCap <= 0) return null;
  if (!Number.isInteger(slots) || slots <= 0 || slots > players.length) return null;
  if (!players.every(validPlayer)) return null;
  type Cell = { proj: number; picks: number[] } | null;
  const dp: Cell[][] = Array.from({ length: slots + 1 }, () =>
    Array.from({ length: salaryCap + 1 }, () => null as Cell),
  );
  const row0 = dp[0];
  if (row0 === undefined) return null;
  row0[0] = { proj: 0, picks: [] };
  players.forEach((pl, idx) => {
    for (let k = slots; k >= 1; k--) {
      const prevRow = dp[k - 1];
      const curRow = dp[k];
      if (prevRow === undefined || curRow === undefined) continue;
      for (let c = salaryCap; c >= pl.salary; c--) {
        const prev = prevRow[c - pl.salary];
        if (prev === null || prev === undefined) continue;
        const cand: Cell = { proj: prev.proj + pl.proj, picks: [...prev.picks, idx] };
        const cur = curRow[c];
        if ((cur === null || cur === undefined) && cand.proj >= 0) curRow[c] = cand;
        else if (cur !== null && cur !== undefined && cand.proj > cur.proj) curRow[c] = cand;
      }
    }
  });
  const finalRow = dp[slots];
  if (finalRow === undefined) return null;
  let best: { proj: number; picks: number[] } | null = null;
  let bestCap = 0;
