    "mechanism": (
        "Feed hygiene primitives: record normalization (string trimming, numeric-string coercion, "
        "null/empty dropping with a dropped-key audit trail), required-field validation, and key-based "
        "deduplication keeping the first occurrence."
    ),
    "ingest_role": "feed hygiene (normalization, required-field validation, dedupe)",
    "config": 'enabled: false,\n  method: "feed record normalization + required-field validation + dedupe",',
    "module": '''
const NUMERIC_RE = /^[-+]?(\\d+\\.?\\d*|\\.\\d+)([eE][-+]?\\d+)?$/;

/**

 * Normalize a raw feed record: trim strings, coerce numeric strings to numbers,
 * drop null/undefined/empty values. Returns the normalized record plus dropped keys.
 */
export function normalizeFeedRecord(
  raw: Record<string, unknown>,
): { record: Record<string, unknown>; dropped: string[] } | null {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return null;
  const record: Record<string, unknown> = {};
  const dropped: string[] = [];
  for (const [k, v] of Object.entries(raw)) {
    if (v === null || v === undefined || v === "") {
      dropped.push(k);
      continue;
    }
    if (typeof v === "string") {
      const t = v.trim();
      if (t === "") {
        dropped.push(k);
        continue;
      }
      record[k] = NUMERIC_RE.test(t) ? Number(t) : t;
    } else {
      record[k] = v;
    }
  }
  return { record, dropped };
}

/** Required-field validation: returns the list of missing or empty keys. */
export function validateRequired(record: Record<string, unknown>, required: readonly string[]): string[] | null {
  if (typeof record !== "object" || record === null || Array.isArray(record)) return null;
  return required.filter((k) => {
    const v = record[k];
    return v === undefined || v === null || v === "";
  });
}

/** Deduplicate rows by key, keeping the first occurrence. */
export function dedupeByKey<T>(
  rows: readonly T[],
  key: (row: T) => string,
): { rows: T[]; duplicates: number } | null {
  if (!Array.isArray(rows) || typeof key !== "function") return null;
  const seen = new Set<string>();
  const out: T[] = [];
  let duplicates = 0;
  for (const r of rows) {
    const k = key(r);
    if (typeof k !== "string") return null;
    if (seen.has(k)) {
      duplicates++;
      continue;
    }
    seen.add(k);
    out.push(r);
  }
  return { rows: out, duplicates };
}
''',
    "test": '''import { describe, expect, it } from "vitest";
import * as mod from "./%%FILE%%";

describe("data-infra feed hygiene (arXiv:%%ARXIV%%)", () => {
