def sanitize_jsdoc(s: str) -> str:
    return s.replace("*/", "* /")


def sanitize_gate_literal(s: str) -> str:
    return s.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${")


def wrap_jsdoc(text: str, width: int = 100) -> str:
    """Greedy word-wrap for JSDoc comment bodies."""
    words = text.split()
    lines: list[str] = []
    cur = ""
    for w in words:
        if len(cur) + 1 + len(w) > width and cur:
            lines.append(cur)
            cur = w
        else:
            cur = (cur + " " + w).strip()
    if cur:
        lines.append(cur)
    return "\n * ".join(lines)


def header_for(rec: dict, filename: str) -> str:
    lane = LANES[rec["normalized_lane"]]
    gate = sanitize_jsdoc(rec["gate"])
    imp = sanitize_jsdoc(rec["improvement"])
    gate_lit = sanitize_gate_literal(rec["gate"])
    slug = rec["arxiv_id"].replace(".", "-")
    parts = [
        "/**",
