  it("quantile regression recovers the median of symmetric noise", () => {
    const rand = mulberry32(11);
    const X: number[][] = [];
    const y: number[] = [];
    for (let i = 0; i < 800; i++) {
      const x = rand() * 4 - 2;
      X.push([1, x]);
      y.push(2 * x + randn(rand));
