    const X = Array.from({ length: 20 }, () => [rand(), rand(), rand(), rand()]);
    const h = lstmSequence(X, W);
    expect(h.length).toBe(8);
    expect(h.every((v) => Math.abs(v) <= 1 && Number.isFinite(v))).toBe(true);
  });
  it("cell state carries information across steps", () => {
