block("emax", """
function phiStd(x: number): number {
  return Math.exp(-0.5 * x * x) / 2.5066282746310002;
}

function PhiStd(x: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = 0.3989422804014327 * Math.exp(-x * x / 2);
  const p = d * t * (0.31938153 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  return x > 0 ? 1 - p : p;
}

/**
 * Closed-form E[max(X, Y)] for bivariate Gaussian (mu1, mu2, s1, s2, rho).
 * Used for the 2-entry Showdown duel optimizer.
 */
export function expectedMax2(
  mu1: number,
  mu2: number,
  s1: number,
  s2: number,
  rho: number,
): number {
  const sd = Math.sqrt(Math.max(1e-12, s1 * s1 + s2 * s2 - 2 * rho * s1 * s2));
  const d = (mu1 - mu2) / sd;
  return mu1 * PhiStd(d) + mu2 * PhiStd(-d) + sd * phiStd(d);
}

/** Greedy sequential n-entry portfolio via moment-matched Gaussian conditioning. */
export function emaxPortfolioGreedy(
  mus: number[],
  sigmas: number[],
  rhos: number[][],
  k: number,
): number[] {
  const n = mus.length;
  const chosen: number[] = [];
  const remaining = new Set(Array.from({ length: n }, (_, i) => i));
  // running max approximated as Gaussian with matched moments
  let mMean = -Infinity;
  let mVar = 0;
  for (let t = 0; t < k && remaining.size > 0; t++) {
    let best = -1;
    let bestV = -Infinity;
    for (const i of remaining) {
      const rho = chosen.length === 0 ? 0 : avgCorr(i, chosen, rhos);
      const sd = Math.sqrt(Math.max(1e-12, sigmas[i]! ** 2 + mVar - 2 * rho * sigmas[i]! * Math.sqrt(mVar)));
      const d = chosen.length === 0 ? Infinity : (mus[i]! - mMean) / sd;
      const gain = chosen.length === 0 ? mus[i]! : sd * phiStd(d) + (mus[i]! - mMean) * PhiStd(d);
      if (gain > bestV) {
        bestV = gain;
        best = i;
      }
    }
    chosen.push(best);
    remaining.delete(best);
    // moment-match the new running max (assume independence for the update)
    if (t === 0) {
      mMean = mus[best]!;
      mVar = sigmas[best]! ** 2;
    } else {
      const sd = Math.sqrt(Math.max(1e-12, sigmas[best]! ** 2 + mVar));
      const d = (mus[best]! - mMean) / sd;
      const newMean = mus[best]! * PhiStd(d) + mMean * PhiStd(-d) + sd * phiStd(d);
      mVar = Math.max(1e-9, mVar * 0.9); // shrink: max concentrates
      mMean = newMean;
    }
  }
  return chosen;
}

function avgCorr(i: number, chosen: number[], rhos: number[][]): number {
  if (chosen.length === 0) return 0;
  return chosen.reduce((s, j) => s + rhos[i]![j]!, 0) / chosen.length;
}
""", """
describe("emax", () => {
  it("expectedMax2 matches Monte Carlo", () => {
    const rand = mulberry32(371);
    const mu1 = 100;
    const mu2 = 95;
    const s1 = 20;
    const s2 = 25;
    const rho = 0.4;
    const closed = expectedMax2(mu1, mu2, s1, s2, rho);
    const n = 60000;
    let s = 0;
    for (let i = 0; i < n; i++) {
      const z1 = randn(rand);
      const z2 = randn(rand);
      const x = mu1 + s1 * z1;
      const y = mu2 + s2 * (rho * z1 + Math.sqrt(1 - rho * rho) * z2);
      s += Math.max(x, y);
    }
    expect(Math.abs(closed - s / n)).toBeLessThan(0.6);
    expect(closed).toBeGreaterThan(Math.max(mu1, mu2));
  });
  it("expectedMax2 reduces to max of means when variance -> 0", () => {
    expect(expectedMax2(100, 95, 1e-9, 1e-9, 0)).toBeCloseTo(100, 3);
  });
  it("emaxPortfolioGreedy picks k distinct entries", () => {
    const mus = [100, 98, 96, 94, 92];
    const sigmas = [20, 20, 20, 20, 20];
    const rhos = mus.map(() => mus.map(() => 0.3));
    const chosen = emaxPortfolioGreedy(mus, sigmas, rhos, 3);
    expect(chosen.length).toBe(3);
    expect(new Set(chosen).size).toBe(3);
    expect(chosen[0]).toBe(0); // highest mean first
  });
});
