    const diverse = [[0, 3, 4], [1, 4, 5], [2, 3, 5]];
    expect(chalkIndex(ownership, concentrated)).toBeGreaterThan(chalkIndex(ownership, diverse));
  });
  it("contrarianFilter removes template-hugging lineups", () => {
    const lineups = [[0, 1, 2], [3, 4, 5]];
