block("darts", """
/** Softmax over architecture logits. */
export function archSoftmax(alphas: number[]): number[] {
  const mx = Math.max(...alphas);
  const e = alphas.map((a) => Math.exp(a - mx));
  const s = e.reduce((x, y) => x + y, 0);
  return e.map((v) => v / s);
}

/** Mixed-op output: convex combination of candidate ops. */
export function mixedOp(
  weights: number[],
  ops: ((x: number[]) => number[])[],
  x: number[],
): number[] {
  const w = archSoftmax(weights);
  const d = ops[0]!(x).length;
  const out = new Array<number>(d).fill(0);
  ops.forEach((op, i) => {
    const y = op(x);
    for (let j = 0; j < d; j++) out[j]! += w[i]! * y[j]!;
  });
  return out;
}

/** Single-level DARTS gradient step on architecture weights (toy). */
export function dartsArchStep(
  alphas: number[],
  valLoss: (w: number[]) => number,
  lr: number,
  h = 1e-3,
): number[] {
  const g = alphas.map((_, i) => {
    const ap = alphas.slice();
    const am = alphas.slice();
    ap[i]! += h;
    am[i]! -= h;
    return (valLoss(ap) - valLoss(am)) / (2 * h);
  });
  return alphas.map((a, i) => a - lr * g[i]!);
}

/** Discretize: argmax op per mixed edge. */
export function discretizeArch(alphaEdges: number[][]): number[] {
  return alphaEdges.map((alphas) => alphas.indexOf(Math.max(...alphas)));
}
""", """
describe("darts", () => {
  it("mixedOp interpolates between ops", () => {
    const opA = (x: number[]): number[] => x.map((v) => v);
    const opB = (x: number[]): number[] => x.map((v) => -v);
    const out = mixedOp([10, 10], [opA, opB], [1, 2]);
    expect(out[0]).toBeCloseTo(0, 8);
  });
  it("dartsArchStep moves toward the better op", () => {
    const valLoss = (w: number[]): number => {
      const s = archSoftmax(w);
      return s[0]! * 1.0 + s[1]! * 0.0; // op1 is better
    };
    let a = [0, 0];
    for (let i = 0; i < 200; i++) a = dartsArchStep(a, valLoss, 0.5);
    expect(discretizeArch([a])[0]).toBe(1);
  });
});
""")

