block("nasbench", """
/** Deterministic toy NAS-bench query: accuracy from an architecture encoding. */
export function nasBenchQuery(enc: number[]): { acc: number; params: number } {
  const acc = 0.85 + 0.1 * Math.tanh(enc.reduce((s, v, i) => s + v * Math.sin(i + 1), 0) / enc.length);
  const params = 1e6 * (1 + enc.reduce((s, v) => s + Math.abs(v), 0));
  return { acc, params };
}

/** Random search over encodings; returns best. */
export function nasRandomSearch(
  n: number,
  dim: number,
  rand: () => number,
): { enc: number[]; acc: number } {
  let best = { enc: [] as number[], acc: -Infinity };
  for (let i = 0; i < n; i++) {
    const enc = Array.from({ length: dim }, () => rand());
    const { acc } = nasBenchQuery(enc);
    if (acc > best.acc) best = { enc, acc };
  }
  return best;
}

/** Latency-aware objective: acc - lambda * log(params). */
export function latencyObjective(acc: number, params: number, lambda: number): number {
  return acc - lambda * Math.log(params);
}
""", """
describe("nasbench", () => {
  it("nasBenchQuery is deterministic and bounded", () => {
    const a = nasBenchQuery([0.1, 0.5, 0.9]);
    const b = nasBenchQuery([0.1, 0.5, 0.9]);
    expect(a.acc).toBe(b.acc);
    expect(a.acc).toBeGreaterThan(0.5);
    expect(a.acc).toBeLessThan(1);
  });
  it("nasRandomSearch improves over a single draw", () => {
    const rand = mulberry32(401);
    const single = nasBenchQuery(Array.from({ length: 6 }, () => rand())).acc;
    const best = nasRandomSearch(200, 6, rand);
    expect(best.acc).toBeGreaterThanOrEqual(single - 1e-9);
    expect(best.acc).toBeGreaterThan(0.85);
  });
});
