# ---------------- EM mixtures ----------------
block("em", """
function gauss1d(x: number, mu: number, s2: number): number {
  return Math.exp(-((x - mu) ** 2) / (2 * s2)) / Math.sqrt(2 * Math.PI * s2);
}

/** 1D two-component Gaussian mixture EM. */
export function emGaussianMixture1d(
  x: number[],
  iters: number,
): { pi: number; mu1: number; mu2: number; s1: number; s2: number; ll: number[] } {
  let pi = 0.5;
  let mu1 = Math.min(...x);
  let mu2 = Math.max(...x);
  let s1 = 1;
  let s2 = 1;
  const ll: number[] = [];
  for (let it = 0; it < iters; it++) {
    // E step
    const gamma = x.map((xi) => {
      const a = pi * gauss1d(xi, mu1, s1);
      const b = (1 - pi) * gauss1d(xi, mu2, s2);
      return a / Math.max(1e-300, a + b);
    });
    // M step
    const n1 = gamma.reduce((a, b) => a + b, 0);
    const n2 = x.length - n1;
    pi = n1 / x.length;
    mu1 = gamma.reduce((s, g, i) => s + g * x[i]!, 0) / Math.max(1e-12, n1);
    mu2 = gamma.reduce((s, g, i) => s + (1 - g) * x[i]!, 0) / Math.max(1e-12, n2);
    s1 = Math.max(1e-6, gamma.reduce((s, g, i) => s + g * (x[i]! - mu1) ** 2, 0) / Math.max(1e-12, n1));
    s2 = Math.max(1e-6, gamma.reduce((s, g, i) => s + (1 - g) * (x[i]! - mu2) ** 2, 0) / Math.max(1e-12, n2));
    ll.push(x.reduce((s, xi) => s + Math.log(Math.max(1e-300, pi * gauss1d(xi, mu1, s1) + (1 - pi) * gauss1d(xi, mu2, s2))), 0));
  }
  return { pi, mu1, mu2, s1, s2, ll };
}

/** EM log-likelihood is monotone non-decreasing. */
export function emMonotone(ll: number[]): boolean {
  return ll.every((v, i) => i === 0 || v >= ll[i - 1]! - 1e-9);
}
""", """
describe("em", () => {
  it("EM recovers mixture components and is monotone", () => {
    const rand = mulberry32(411);
    const x = Array.from({ length: 400 }, () =>
      rand() < 0.4 ? 20 + randnEm(rand) * 4 : 35 + randnEm(rand) * 5,
    );
    const { pi, mu1, mu2, ll } = emGaussianMixture1d(x, 60);
    expect(emMonotone(ll)).toBe(true);
    const mus = [mu1, mu2].sort((a, b) => a - b);
    expect(Math.abs(mus[0]! - 20)).toBeLessThan(2);
    expect(Math.abs(mus[1]! - 35)).toBeLessThan(2);
    expect(Math.abs(pi - 0.4)).toBeLessThan(0.1);
  });
});

function randnEm(rand: () => number): number {
  let u = 0;
  while (u === 0) u = rand();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rand());
}
""")

# ---------------- Kelly ----------------
block("kelly", """
/** Kelly fraction for a binary bet: f* = (bp - q) / b. */
export function kellyBinary(p: number, b: number): number {
  const q = 1 - p;
  return (b * p - q) / b;
}

/** Fractional Kelly with drawdown guard: cap fraction at maxFrac. */
export function kellySized(
  p: number,
  b: number,
  frac: number,
  maxFrac: number,
): number {
  const f = kellyBinary(p, b) * frac;
  return Math.max(0, Math.min(maxFrac, f));
}

/** Drawdown-gated sizing: scale down after drawdown exceeds threshold. */
export function drawdownGate(
  baseSize: number,
  peak: number,
  current: number,
  maxDD: number,
): number {
  const dd = (peak - current) / Math.max(1e-9, peak);
  if (dd >= maxDD) return 0;
  return baseSize * (1 - dd / maxDD);
}

/** Probability of ruin approx for repeated Kelly bets (rough). */
export function kellyGrowthRate(p: number, b: number, f: number): number {
  const q = 1 - p;
  const win = 1 + f * b;
  const lose = 1 - f;
  if (win <= 0 || lose <= 0) return -Infinity;
  return p * Math.log(win) + q * Math.log(lose);
}
""", """
describe("kelly", () => {
  it("kellyBinary matches the closed form", () => {
    expect(kellyBinary(0.6, 1)).toBeCloseTo(0.2, 10);
    expect(kellyBinary(0.5, 1)).toBeCloseTo(0, 10);
  });
  it("no edge means no bet", () => {
    expect(kellySized(0.4, 1, 0.5, 0.25)).toBe(0);
  });
  it("drawdownGate cuts size at the threshold", () => {
    expect(drawdownGate(100, 1000, 800, 0.2)).toBe(0);
    expect(drawdownGate(100, 1000, 950, 0.2)).toBeGreaterThan(0);
    expect(drawdownGate(100, 1000, 950, 0.2)).toBeLessThan(100);
  });
  it("growth rate is maximized at full Kelly (unimodal)", () => {
    const p = 0.6;
    const b = 1;
    const g = (f: number): number => kellyGrowthRate(p, b, f);
    expect(g(0.2)).toBeGreaterThan(g(0.1));
    expect(g(0.2)).toBeGreaterThan(g(0.4));
  });
});
""")

