block("qa2", """
/** Token-level F1 between prediction and reference. */
export function tokenF1(pred: string, ref: string): number {
  const pt = new Set(pred.toLowerCase().split(/\s+/).filter(Boolean));
  const rt = new Set(ref.toLowerCase().split(/\s+/).filter(Boolean));
  if (pt.size === 0 && rt.size === 0) return 1;
  let inter = 0;
  for (const t of pt) if (rt.has(t)) inter++;
  if (inter === 0) return 0;
  const prec = inter / pt.size;
  const rec = inter / rt.size;
  return (2 * prec * rec) / (prec + rec);
}

/** Exact match (normalized). */
export function exactMatch(pred: string, ref: string): number {
  const norm = (s: string): string => s.toLowerCase().replace(/[^\w\s]/g, "").trim();
  return norm(pred) === norm(ref) ? 1 : 0;
}

/** Retrieval recall@k for a question (was gold passage retrieved?). */
export function retrievalHit(ranked: string[], gold: string, k: number): number {
  return ranked.slice(0, k).includes(gold) ? 1 : 0;
}

/** Hallucination rate: fraction of answers not grounded in any retrieved passage. */
export function hallucinationRate(grounded: boolean[]): number {
  if (grounded.length === 0) return 0;
  return grounded.filter((g) => !g).length / grounded.length;
}
