  });
  it("exactMatch is strict", () => {
    expect(exactMatch("Patrick Mahomes", "patrick mahomes")).toBe(1);
    expect(exactMatch("Mahomes", "Patrick Mahomes")).toBe(0);
  });
  it("hallucinationRate counts ungrounded answers", () => {
    expect(hallucinationRate([true, false, true, false])).toBe(0.5);
