    expect(t[0]).toBeCloseTo(0.01, 10);
  });
  it("consistencyLoss is 0 for identical outputs", () => {
    expect(consistencyLoss([1, 2], [1, 2])).toBe(0);
    expect(consistencyLoss([1, 2], [2, 3])).toBe(1);
  });
});
