        " * ACCEPTANCE GATE (verbatim):",
        f" * {jsdoc_escape(rec['gate'])}",
        " *",
        *[f" * {l}" for l in GATE_STATUS.split("\n")],
        " *",
        f" * owner: {rec['owner']} | bucket: {rec['bucket']} | lane: {rec['normalized_lane']} | verdict: {rec['verdict']} | doctrine: {rec['doctrine_tag']}",
        " */",
    ]
    return "\n".join(lines)


def emit_record(rec, m, outdir: str) -> dict:
    blocks = m["blocks"]
    for b in blocks:
        assert b in BLOCKS, f"unknown block {b}"
    base = f"{slug(rec['arxiv_id'])}-{m['desc']}"
    subdir = m.get("dir") or LANE_DIR[rec["normalized_lane"]]
    d = os.path.join(outdir, subdir)
    os.makedirs(d, exist_ok=True)

    ts_parts = [BLOCKS[b]["ts"] for b in blocks]
    module = (
        header_for(rec, m["mech"])
        + "\n\nexport const ENABLED = false;\n\n"
        + "\n\n".join(ts_parts)
        + "\n"
    )
    mod_path = os.path.join(d, base + ".ts")
    with open(mod_path, "w") as f:
        f.write(module)

    exports: list[str] = []
    for b in blocks:
        for n in EXPORT_RE.findall(BLOCKS[b]["ts"]):
            if n not in exports:
                exports.append(n)
    import_block = "import {\n" + "".join(f"  {n},\n" for n in exports) + f"}} from \"./{base}.js\";\n"
    test_src = (
        'import { describe, it, expect } from "vitest";\n'
        + import_block
        + "\n"
        + TEST_HELPERS
        + "\n"
        + "\n\n".join(BLOCKS[b]["test"] for b in blocks)
        + "\n"
    )
    test_path = os.path.join(d, base + ".test.ts")
    with open(test_path, "w") as f:
        f.write(test_src)
    return {
        "arxiv_id": rec["arxiv_id"],
        "dir": subdir,
        "module": os.path.join("packages/prediction-engine/src", subdir, base + ".ts"),
        "test": os.path.join("packages/prediction-engine/src", subdir, base + ".test.ts"),
        "blocks": blocks,
    }


def main() -> None:
    recs = json.load(open(SLICE))
    assert len(recs) == 100, f"expected 100 records, got {len(recs)}"
    manifest = []
    seen = set()
    for rec in recs:
        aid = rec["arxiv_id"]
        assert aid in MAPPING, f"no mapping for {aid}"
        m = MAPPING[aid]
        base = f"{slug(aid)}-{m['desc']}"
        assert re.fullmatch(r"[a-z0-9][a-z0-9-]*", base), f"non-kebab base {base}"
        assert base not in seen, f"duplicate base {base}"
        seen.add(base)
        subdir = m.get("dir") or LANE_DIR[rec["normalized_lane"]]
        for suffix in (".ts", ".test.ts"):
            dest = f"packages/prediction-engine/src/{subdir}/{base}{suffix}"
            assert dest not in MAIN_FILES, f"collision with origin/main: {dest}"
        manifest.append(emit_record(rec, m, OUT))
    with open(os.path.join(OUT, "manifest.json"), "w") as f:
        json.dump(manifest, f, indent=1)
    print(f"emitted {len(manifest)} records -> {OUT}")


if __name__ == "__main__":
    main()

