def w(prefix: str, text: str, width: int = 98):
    """Wrap text into lines starting with prefix."""
    out, cur = [], prefix.rstrip() + " "
    for word in text.replace("\n", " ").split():
        if len(cur) + len(word) + 1 > width and cur.strip() != prefix.strip():
            out.append(cur.rstrip()); cur = prefix + word + " "
        else:
