/** Role-specific process-noise / interaction parameters. */
export interface RoleParams {
  /** Role label, e.g. "QB". */
  role: string;
  /** Process-noise scale for this role (yards/sqrt(s)). */
  sigma: number;
  /** Interaction gain toward the nearest opponent. */
  interaction: number;
