  observedRate: number,
  nullRate: number,
): { ratio: number; passes: boolean } {
  if (nullRate <= 0) throw new Error("burstinessGateTest: nullRate > 0");
  const ratio = observedRate / nullRate;
  return { ratio, passes: ratio >= 1.15 };
}
