export function executedQueryScore(
  got: readonly (string | number)[][],
  want: readonly (string | number)[][],
): number {
  const norm = (rows: readonly (string | number)[][]) =>
    rows.map((r) => JSON.stringify(r)).sort().join("|");
  return norm(got) === norm(want) ? 1 : 0;
}

