  for (let i = 0; i < chunks.length; i++) {
    for (let j = i + 1; j < chunks.length; j++) {
      const a = chunks[i]?.pos ?? [0, 0];
      const b = chunks[j]?.pos ?? [0, 0];
      s += Math.hypot(a[0] - b[0], a[1] - b[1]);
      n++;
    }
  }
  return s / Math.max(1, n);
