/** One DFS portfolio candidate with its conformal interval. */
export interface PortfolioCandidate {
  id: string;
  /** Point projection. */
  proj: number;
  /** Conformal interval half-width. */
  halfWidth: number;
  /** Expected rake cost. */
  rake: number;
  /** Projected ownership (0..1). */
  ownership: number;
