/** Binary KL divergence (the information-gain weight). */
export function infoGain(pBefore: number, pAfter: number): number {
  const c = (p: number) => Math.min(1 - 1e-9, Math.max(1e-9, p));
  const a = c(pBefore);
  const b = c(pAfter);
  return b * Math.log(b / a) + (1 - b) * Math.log((1 - b) / (1 - a));
