export function identifiabilityFlag(
  moves: readonly LineMove[],
  noiseFloor: number,
): boolean {
  const total = moves.reduce((s, m) => s + infoGain(m.pBefore, m.pAfter), 0);
  return total < noiseFloor; // true = non-identifiable, do not update
