export function hazardDecayWeight(hoursBeforeClose: number, halfLifeHrs: number): number {
  if (halfLifeHrs <= 0) throw new Error("hazardDecayWeight: halfLifeHrs > 0");
  const r = Math.max(0, hoursBeforeClose) / halfLifeHrs;
  return Math.exp(r * r);
}

