export function anchorRobustFilter(
  games: readonly { gameId: string; moves: TimedMove[] }[],
  halfLifeHrs: number,
  maxPostAnchorShare: number,
): string[] {
  return games
    .filter((g) => 1 - driftShare(g.moves, halfLifeHrs) <= maxPostAnchorShare)
    .map((g) => g.gameId);
}
