  playoffBoost: number,
): number {
  if (draws <= 0) throw new Error("mcPositivity: draws > 0");
  let pos = 0;
  for (let d = 0; d < draws; d++) {
    const noisy = new Map<string, number[]>();
    for (const [id, w] of proj) {
      const sd = projSd.get(id) ?? w.map(() => 0);
