  const rank = new Map(modelOrder.map((t, i) => [t, i]));
  let swaps = 0;
  let total = 0;
  for (let i = 0; i < standings.length; i++) {
    for (let j = i + 1; j < standings.length; j++) {
      total++;
      if ((rank.get(standings[i]!) ?? 0) > (rank.get(standings[j]!) ?? 0)) swaps++;
    }
  }
