export function boxCount(
  defenders: readonly { x: number; y: number }[],
  losY: number,
  ballX: number,
): number {
  return defenders.filter((d) => Math.abs(d.y - losY) <= 5 && Math.abs(d.x - ballX) <= 12).length;
